window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a6973e9bc6ba6008"]={"versions": [{"id": "FIG-a6973e9bc6ba6008", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt des AUTOSAR System Templates (<code>AUTOSAR_TPS_SystemTemplate</code>, PDU-Beschreibung im FIBEX-Modell, R4.2.2).\n</li><li><strong>Technischer Zweck:</strong> Modellierung des PDU-Multiplexings/Packings von mehreren logischen PDUs (<code>ContainedIPdu</code>) in einen gemeinsamen Transportrahmen (<code>ContainerIPdu</code>).\n</li><li><strong>Architektur-Einordnung:</strong> Dient als formale Entwurfsbasis für Kommunikationsstacks mit großen Frame-Kapazitäten (insbesondere CAN FD, FlexRay, Ethernet/SomeIP). Das Modell steuert im BSW-Stack (vor allem <code>PduR</code>, alternativ spezialisierte Module wie <code>IpduM</code>) das Packen, Puffern, Timen und Entpacken heterogener PDUs zur Bandbreitenoptimierung und Overhead-Reduktion.\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metamodell-Klassen &amp; Vererbungen</h5>\n<ul class=\"fig-list\"><li><strong><code>Pdu</code></strong> <em>(«FibexElement»)</em>:\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse aller Protocol Data Units.\n</li><li>Attribute: <code>length [0..1] : Integer</code> (statische PDU-Länge in Byte), <code>metaDataLength [0..1] : PositiveInteger</code> (Zusatzbytes für dynamische Metadaten, z. B. Adressierung oder CAN-ID).\n</li></ul>\n</li><li><strong><code>IPdu</code></strong>:\n<ul class=\"fig-list\"><li>Spezialisierung von <code>Pdu</code>. Repräsentiert Interaktionsschicht-PDUs.\n</li><li>Komposition: Hält <code>0..1</code> Instanz von <code>ContainedIPduProps</code> (Kennzeichnung als potentiell einbettbare PDU).\n</li></ul>\n</li><li><strong><code>ContainerIPdu</code></strong>:\n<ul class=\"fig-list\"><li>Spezialisierung von <code>IPdu</code>. Repräsentiert die aggregierende Hüll-PDU.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>containerTimeout [0..1] : TimeValue</code>: Maximales Wartefenster bis zum Zwangsversand unvollständig gefüllter Container.\n</li><li><code>containerTrigger [0..1] : ContainerIPduTriggerEnum</code>: Globales Auslöseverhalten für den Container.\n</li><li><code>headerType [1] : ContainerIPduHeaderTypeEnum</code>: Pflichtangabe zum Header-Format der eingebetteten PDUs.\n</li><li><code>rxAcceptContainedIPdu [1] : RxAcceptContainedIPduEnum</code>: Filterstrategie bei der PDU-Extraktion auf Empfangsseite.\n</li><li><code>thresholdSize [0..1] : PositiveInteger</code>: Füllstandsschwelle in Bytes, bei deren Erreichen/Überschreiten der Container sofort ausgelöst wird.\n</li></ul>\n</li></ul>\n</li><li><strong><code>ContainedIPduProps</code></strong>:\n<ul class=\"fig-list\"><li>Eigenschafts-Container für eingebettete I-PDUs innerhalb eines Containers.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>collectionSemantics [1] : ContainedIPduCollectionSemanticsEnum</code>: Update- und Pufferstrategie (<code>lastIsBest</code> vs. <code>queued</code>).\n</li><li><code>headerIdLongHeader [0..1] : PositiveInteger</code>: 32-Bit-ID bei Verwendung langer Header.\n</li><li><code>headerIdShortHeader [0..1] : PositiveInteger</code>: 24-Bit-ID bei Verwendung kurzer Header.\n</li><li><code>timeout [0..1] : TimeValue</code>: Gültigkeits- bzw. Sammeltimeout der spezifischen Contained I-PDU.\n</li><li><code>trigger [0..1] : PduCollectionTriggerEnum</code>: Legt fest, ob das Eintreffen dieser PDU den Container-Versand initiiert.\n</li></ul>\n</li></ul>\n</li><li><strong><code>PduTriggering</code></strong> <em>(«Identifiable»)</em>:\n<ul class=\"fig-list\"><li>Abbildung einer PDU auf einen Kommunikationsport/Kanal.\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li><code>1..*</code> <code>PduTriggering</code> verweist auf genau <code>1</code> <code>+iPdu</code> (<code>Pdu</code>).\n</li><li><code>1</code> <code>ContainerIPdu</code> aggregiert/referenziert <code>0..*</code> <code>+containedPduTriggering</code> (<code>PduTriggering</code>).\n</li></ul>\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Enumerationen</h5>\n<ul class=\"fig-list\"><li><strong><code>ContainerIPduHeaderTypeEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>shortHeader</code>: Kompakter Header (24 Bit Header-ID + 8 Bit Längenfeld = 4 Bytes Overhead; Nutzlast max. 255 Bytes je Contained PDU).\n</li><li><code>longHeader</code>: Erweiterter Header (32 Bit Header-ID + 32 Bit Längenfeld = 8 Bytes Overhead; für große PDUs/Ethernet).\n</li></ul>\n</li><li><strong><code>RxAcceptContainedIPduEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>acceptAll</code>: Akzeptiert alle im Stream empfangenen Contained-Header (auch unbekannte IDs werden akzeptiert/überlesen).\n</li><li><code>acceptConfigured</code>: Nur explizit im System Template hinterlegte Contained-PDU-IDs werden akzeptiert; unbekannte IDs werden verworfen.\n</li></ul>\n</li><li><strong><code>ContainerIPduTriggerEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>firstContainedTrigger</code>: Container-Übertragung wird getriggert, sobald die erste triggerberechtigte Contained PDU platziert wurde.\n</li><li><code>defaultTrigger</code>: Standard-Auswertung über <code>thresholdSize</code>, <code>containerTimeout</code> oder PDU-spezifischen Trigger.\n</li></ul>\n</li><li><strong><code>ContainedIPduCollectionSemanticsEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>lastIsBest</code>: Bei wiederholtem Empfang vor dem Container-Versand wird die vorherige Instanz im Sendepuffer überschrieben.\n</li><li><code>queued</code>: Jede empfangene Instanz wird sequentiell in eine FIFO eingereiht und mehrfach verpackt.\n</li></ul>\n</li><li><strong><code>PduCollectionTriggerEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>always</code>: Bereitstellung dieser I-PDU triggert sofort den Versand des übergeordneten Containers.\n</li><li><code>never</code>: Bereitstellung füllt lediglich den Puffer; Versand erfolgt rein über Schwellwert, Timer oder andere I-PDUs.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Sende-Pfad (TX-Aggregation / Packing)</h5>\n<ol class=\"fig-list\"><li><strong>PDU-Anlieferung:</strong> Eine obere Schicht (COM, SecOC, Dcm) übergibt eine I-PDU via <code>PduR_Transmit()</code> an die Routing Engine.\n</li><li><strong>Klassifikation &amp; Pufferung:</strong> \n<ul class=\"fig-list\"><li>Ist der Zielpfad eine <code>ContainerIPdu</code>, prüft das verarbeitende Modul (<code>PduR</code> / IPDU-Multiplexer) <code>ContainedIPduProps</code>.\n</li><li>Bei <code>collectionSemantics == lastIsBest</code> wird ein bestehender Eintrag im TX-Container-Puffer aktualisiert. Bei <code>queued</code> wird die PDU an das Ende des Aggregationspuffers angehängt.\n</li></ul>\n</li><li><strong>Serialisierung:</strong> Voranstellung des Headers (<code>shortHeader</code> oder <code>longHeader</code>) mit der konfigurierten <code>headerIdShortHeader</code> bzw. <code>headerIdLongHeader</code> und der tatsächlichen DLC/Länge.\n</li><li><strong>Trigger-Prüfung:</strong>\n<ul class=\"fig-list\"><li><strong>Sofort-Trigger:</strong> Falls <code>ContainedIPduProps.trigger == always</code> oder <code>ContainerIPduTriggerEnum == firstContainedTrigger</code>, wird die <code>ContainerIPdu</code> unmittelbar an das Interface (<code>CanIf</code>, <code>SoAd</code>) weitergegeben.\n</li><li><strong>Schwellwert-Trigger:</strong> Überschreitet die aggregierte Gesamtlänge <code>thresholdSize</code>, erfolgt sofortiger Push.\n</li><li><strong>Zeitbasierter Trigger:</strong> Läuft der asynchrone Hardware-/Software-Timer <code>containerTimeout</code> oder das PDU-individuelle <code>timeout</code> ab, wird die <code>ContainerIPdu</code> mit dem aktuellen Füllstand asynchron gesendet.\n</li></ul>\n</li></ol>\n<h5 class=\"fig-section-h5\">Empfangs-Pfad (RX-Disaggregation / Unpacking)</h5>\n<ol class=\"fig-list\"><li><strong>Container-Empfang:</strong> Die vollständige <code>ContainerIPdu</code> trifft über das untere Interface (<code>&lt;Bus&gt;If_RxIndication()</code>) im BSW-Stack ein.\n</li><li><strong>Header-Parsing:</strong> Der Byte-Stream wird sequentiell anhand des <code>headerType</code> geparst (Extraktion von ID und Längenfeld).\n</li><li><strong>Validierung &amp; Filterung:</strong>\n<ul class=\"fig-list\"><li>Stimmt die Header-ID mit einer bekannten <code>containedPduTriggering</code> überein, wird die Nutzlast extrahiert.\n</li><li>Ist die ID unbekannt: Bei <code>acceptConfigured</code> Abbruch bzw. PDU-Verwurf (ggf. Det-Meldung); bei <code>acceptAll</code> Weiterspringen um das Längenfeld zum nächsten Header.\n</li></ul>\n</li><li><strong>Dispatchen:</strong> Extrahierte Contained I-PDUs werden über <code>PduR_&lt;Target&gt;RxIndication()</code> an die jeweiligen Zielmodule verteilt.\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Konfiguration (<code>PduR</code> / CAN FD / Ethernet):</strong>\n<ul class=\"fig-list\"><li>Das Metamodell bildet 1:1 die Konfigurationscontainer <code>PduRContainerIPdu</code> und <code>PduRContainedIPdu</code> im BSW ab.\n</li><li><strong>Konsistenz-Restriktion:</strong> Wenn <code>headerType == shortHeader</code>, muss zwingend <code>headerIdShortHeader</code> gesetzt sein (Bereich: 1 bis 2^24-1). Bei <code>longHeader</code> ist <code>headerIdLongHeader</code> Pflicht (Bereich: 1 bis 2^32-1). Mischbetrieb innerhalb eines Containers ist verboten.\n</li></ul>\n</li><li><strong>Speicher- und Pufferallokation:</strong>\n<ul class=\"fig-list\"><li><code>collectionSemantics == queued</code> erzwingt im BSW-Generat statisch allokierte Ringpuffer (Multi-Element Queues). Entwickler müssen die maximale Queue-Tiefe gegen RAM-Verbrauch und Worst-Case-Latenz abgleichen.\n</li><li><code>lastIsBest</code> minimiert RAM-Overhead (Single-Buffer), führt bei langsamen Buszyklen jedoch zum unbemerkten Verwerfen älterer Datenstände (Data Overwrite).\n</li></ul>\n</li><li><strong>Echtzeit- und Latenz-Design:</strong>\n<ul class=\"fig-list\"><li>Zeitkritische I-PDUs (z. B. Brems-/Lenkanforderungen) müssen zwingend auf <code>trigger = always</code> konfiguriert werden, um ein Verzögern durch <code>containerTimeout</code> zu unterbinden.\n</li><li>Unbedachte Kombinationen von großem <code>thresholdSize</code> und fehlendem <code>containerTimeout</code> können bei unvollständigen Daten zum Blockieren/Verhungern (Starvation) von Contained I-PDUs im Puffer führen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-9c9028f9b9c7f28a", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt des AUTOSAR System Templates (<code>AUTOSAR_TPS_SystemTemplate</code>, PDU-Beschreibung im FIBEX-Modell, R4.2.2).\n</li><li><strong>Technischer Zweck:</strong> Modellierung des PDU-Multiplexings/Packings von mehreren logischen PDUs (<code>ContainedIPdu</code>) in einen gemeinsamen Transportrahmen (<code>ContainerIPdu</code>).\n</li><li><strong>Architektur-Einordnung:</strong> Dient als formale Entwurfsbasis für Kommunikationsstacks mit großen Frame-Kapazitäten (insbesondere CAN FD, FlexRay, Ethernet/SomeIP). Das Modell steuert im BSW-Stack (vor allem <code>PduR</code>, alternativ spezialisierte Module wie <code>IpduM</code>) das Packen, Puffern, Timen und Entpacken heterogener PDUs zur Bandbreitenoptimierung und Overhead-Reduktion.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metamodell-Klassen &amp; Vererbungen</h5>\n<ul class=\"fig-list\"><li><strong><code>Pdu</code></strong> <em>(«FibexElement»)</em>:\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse aller Protocol Data Units.\n</li><li>Attribute: <code>length [0..1] : Integer</code> (statische PDU-Länge in Byte).\n</li></ul>\n</li><li><strong><code>IPdu</code></strong>:\n<ul class=\"fig-list\"><li>Spezialisierung von <code>Pdu</code>. Repräsentiert Interaktionsschicht-PDUs.\n</li><li>Komposition: Hält <code>0..1</code> Instanz von <code>ContainedIPduProps</code> über die Rolle <code>+containedIPduProps</code>.\n</li></ul>\n</li><li><strong><code>ContainerIPdu</code></strong>:\n<ul class=\"fig-list\"><li>Spezialisierung von <code>IPdu</code>. Repräsentiert die aggregierende Hüll-PDU.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>containerTimeout [0..1] : TimeValue</code>: Maximales Wartefenster bis zum Zwangsversand unvollständig gefüllter Container.\n</li><li><code>containerTrigger [0..1] : ContainerIPduTriggerEnum</code>: Globales Auslöseverhalten für den Container.\n</li><li><code>headerType [1] : ContainerIPduHeaderTypeEnum</code>: Pflichtangabe zum Header-Format der eingebetteten PDUs.\n</li><li><code>rxAcceptContainedIPdu [1] : RxAcceptContainedIPduEnum</code>: Filterstrategie bei der PDU-Extraktion auf Empfangsseite.\n</li><li><code>thresholdSize [0..1] : PositiveInteger</code>: Füllstandsschwelle in Bytes, bei deren Erreichen/Überschreiten der Container sofort ausgelöst wird.\n</li><li><code>unusedBitPattern [0..1] : PositiveInteger</code>: Bitmuster zum Auffüllen ungenutzter Bereiche im Container.\n</li></ul>\n</li></ul>\n</li><li><strong><code>ContainedIPduProps</code></strong>:\n<ul class=\"fig-list\"><li>Eigenschafts-Container für eingebettete I-PDUs innerhalb eines Containers.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>collectionSemantics [1] : ContainedIPduCollectionSemanticsEnum</code>: Update- und Pufferstrategie (<code>lastIsBest</code> vs. <code>queued</code>).\n</li><li><code>headerIdLongHeader [0..1] : PositiveInteger</code>: 32-Bit-ID bei Verwendung langer Header.\n</li><li><code>headerIdShortHeader [0..1] : PositiveInteger</code>: 24-Bit-ID bei Verwendung kurzer Header.\n</li><li><code>offset [0..1] : PositiveInteger</code>: Feste Byte-Offset-Position der Contained PDU innerhalb des Containers (relevant bei fester Platzierung ohne Header).\n</li><li><code>timeout [0..1] : TimeValue</code>: Gültigkeits- bzw. Sammeltimeout der spezifischen Contained I-PDU.\n</li><li><code>trigger [0..1] : PduCollectionTriggerEnum</code>: Legt fest, ob das Eintreffen dieser PDU den Container-Versand initiiert.\n</li><li><code>updateIndicationBitPosition [0..1] : PositiveInteger</code>: Bitposition eines Update-Bits zur Erkennung neuer Daten.\n</li></ul>\n</li></ul>\n</li><li><strong><code>PduTriggering</code></strong> <em>(«Identifiable»)</em>:\n<ul class=\"fig-list\"><li>Abbildung einer PDU auf einen Kommunikationsport/Kanal.\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li>Assoziation verweist auf genau <code>1</code> <code>+iPdu</code> (<code>Pdu</code>).\n</li><li><code>1</code> <code>ContainerIPdu</code> aggregiert/referenziert <code>0..*</code> <code>+containedPduTriggering</code> (<code>PduTriggering</code>).\n</li></ul>\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Enumerationen</h5>\n<ul class=\"fig-list\"><li><strong><code>ContainerIPduHeaderTypeEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>shortHeader</code>: Kompakter Header (24 Bit Header-ID + 8 Bit Längenfeld = 4 Bytes Overhead; Nutzlast max. 255 Bytes je Contained PDU).\n</li><li><code>longHeader</code>: Erweiterter Header (32 Bit Header-ID + 32 Bit Längenfeld = 8 Bytes Overhead; für große PDUs/Ethernet).\n</li><li><code>noHeader</code>: Kein Header je Contained PDU (statische Platzierung über Offset).\n</li></ul>\n</li><li><strong><code>RxAcceptContainedIPduEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>acceptAll</code>: Akzeptiert alle im Stream empfangenen Contained-Header (auch unbekannte IDs werden akzeptiert/überlesen).\n</li><li><code>acceptConfigured</code>: Nur explizit im System konfigurierte Contained PDUs werden akzeptiert.\n</li></ul>\n</li><li><strong><code>PduCollectionTriggerEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>always</code>: Jedes Eintreffen dieser Contained I-PDU triggert sofort das Senden des Containers.\n</li><li><code>never</code>: Das Eintreffen dieser Contained I-PDU löst keinen sofortigen Sendevorgang aus (Versand erfolgt zeit- oder schwellwertbasiert).\n</li></ul>\n</li><li><strong><code>ContainerIPduTriggerEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>firstContainedTrigger</code>: Das Eintreffen der ersten Contained PDU startet das Container-Sammelzeitfenster.\n</li><li><code>defaultTrigger</code>: Standard-Triggerlogik für den Container.\n</li></ul>\n</li><li><strong><code>ContainedIPduCollectionSemanticsEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>lastIsBest</code>: Überschreibender Puffer; neuere Instanzen derselben PDU ersetzen ältere.\n</li><li><code>queued</code>: FIFO-Warteschlange; alle eingehenden Instanzen werden sequentiell gesammelt.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Sende-Pfad (TX-Aggregation / Packing)</h5>\n<ol class=\"fig-list\"><li><strong>PDU-Anlieferung:</strong> Eine obere Schicht (COM, SecOC, Dcm) übergibt eine I-PDU via <code>PduR_Transmit()</code> an die Routing Engine.\n</li><li><strong>Klassifikation &amp; Pufferung:</strong> \n<ul class=\"fig-list\"><li>Ist der Zielpfad eine <code>ContainerIPdu</code>, prüft das verarbeitende Modul (<code>PduR</code> / IPDU-Multiplexer) <code>ContainedIPduProps</code>.\n</li><li>Bei <code>collectionSemantics == lastIsBest</code> wird ein bestehender Eintrag im TX-Container-Puffer aktualisiert. Bei <code>queued</code> wird die PDU an das Ende des Aggregationspuffers angehängt.\n</li></ul>\n</li><li><strong>Serialisierung:</strong> Voranstellung des Headers (<code>shortHeader</code> oder <code>longHeader</code>) mit der konfigurierten <code>headerIdShortHeader</code> bzw. <code>headerIdLongHeader</code> und der tatsächlichen DLC/Länge.\n</li><li><strong>Trigger-Prüfung:</strong>\n<ul class=\"fig-list\"><li><strong>Sofort-Trigger:</strong> Falls <code>ContainedIPduProps.trigger == always</code> oder <code>ContainerIPduTriggerEnum == firstContainedTrigger</code>, wird die <code>ContainerIPdu</code> unmittelbar an das Interface (<code>CanIf</code>, <code>SoAd</code>) weitergegeben.\n</li><li><strong>Schwellwert-Trigger:</strong> Überschreitet die aggregierte Gesamtlänge <code>thresholdSize</code>, erfolgt sofortiger Push.\n</li><li><strong>Zeitbasierter Trigger:</strong> Läuft der asynchrone Hardware-/Software-Timer <code>containerTimeout</code> oder das PDU-individuelle <code>timeout</code> ab, wird die <code>ContainerIPdu</code> mit dem aktuellen Füllstand asynchron gesendet.\n</li></ul>\n</li></ol>\n<h5 class=\"fig-section-h5\">Empfangs-Pfad (RX-Disaggregation / Unpacking)</h5>\n<ol class=\"fig-list\"><li><strong>Container-Empfang:</strong> Die vollständige <code>ContainerIPdu</code> trifft über das untere Interface (<code>&lt;Bus&gt;If_RxIndication()</code>) im BSW-Stack ein.\n</li><li><strong>Header-Parsing:</strong> Der Byte-Stream wird sequentiell anhand des <code>headerType</code> geparst (Extraktion von ID und Längenfeld).\n</li><li><strong>Validierung &amp; Filterung:</strong>\n<ul class=\"fig-list\"><li>Stimmt die Header-ID mit einer bekannten <code>containedPduTriggering</code> überein, wird die Nutzlast extrahiert.\n</li><li>Ist die ID unbekannt: Bei <code>acceptConfigured</code> Abbruch bzw. PDU-Verwurf (ggf. Det-Meldung); bei <code>acceptAll</code> Weiterspringen um das Längenfeld zum nächsten Header.\n</li></ul>\n</li><li><strong>Dispatchen:</strong> Extrahierte Contained I-PDUs werden über <code>PduR_&lt;Target&gt;RxIndication()</code> an die jeweiligen Zielmodule verteilt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Konfiguration (<code>PduR</code> / CAN FD / Ethernet):</strong>\n<ul class=\"fig-list\"><li>Das Metamodell bildet 1:1 die Konfigurationscontainer <code>PduRContainerIPdu</code> und <code>PduRContainedIPdu</code> im BSW ab.\n</li><li><strong>Konsistenz-Restriktion:</strong> Wenn <code>headerType == shortHeader</code>, muss zwingend <code>headerIdShortHeader</code> gesetzt sein (Bereich: 1 bis 2^24-1). Bei <code>longHeader</code> ist <code>headerIdLongHeader</code> Pflicht (Bereich: 1 bis 2^32-1). Mischbetrieb innerhalb eines Containers ist verboten.\n</li></ul>\n</li><li><strong>Speicher- und Pufferallokation:</strong>\n<ul class=\"fig-list\"><li><code>collectionSemantics == queued</code> erzwingt im BSW-Generat statisch allokierte Ringpuffer (Multi-Element Queues). Entwickler müssen die maximale Queue-Tiefe gegen RAM-Verbrauch und Worst-Case-Latenz abgleichen.\n</li><li><code>lastIsBest</code> minimiert RAM-Overhead (Single-Buffer), führt bei langsamen Buszyklen jedoch zum unbemerkten Verwerfen älterer Datenstände (Data Overwrite).\n</li></ul>\n</li><li><strong>Echtzeit- und Latenz-Design:</strong>\n<ul class=\"fig-list\"><li>Zeitkritische I-PDUs (z. B. Brems-/Lenkanforderungen) müssen zwingend auf <code>trigger = always</code> konfiguriert werden, um ein Verzögern durch <code>containerTimeout</code> zu unterbinden.\n</li><li>Unbedachte Kombinationen von großem <code>thresholdSize</code> und fehlendem <code>containerTimeout</code> können bei unvollständigen Daten zum Blockieren/Verhungern (Starvation) von Contained I-PDUs im Puffer führen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-83ebb46286560252", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt des AUTOSAR System Templates (<code>AUTOSAR_TPS_SystemTemplate</code>, PDU-Beschreibung im FIBEX-Modell, R4.2.2).\n</li><li><strong>Technischer Zweck:</strong> Modellierung des PDU-Multiplexings/Packings von mehreren logischen PDUs (<code>ContainedIPdu</code>) in einen gemeinsamen Transportrahmen (<code>ContainerIPdu</code>).\n</li><li><strong>Architektur-Einordnung:</strong> Dient als formale Entwurfsbasis für Kommunikationsstacks mit großen Frame-Kapazitäten (insbesondere CAN FD, FlexRay, Ethernet/SomeIP). Das Modell steuert im BSW-Stack (vor allem <code>PduR</code>, alternativ spezialisierte Module wie <code>IpduM</code>) das Packen, Puffern, Timen und Entpacken heterogener PDUs zur Bandbreitenoptimierung und Overhead-Reduktion.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metamodell-Klassen &amp; Vererbungen</h5>\n<ul class=\"fig-list\"><li><strong><code>Pdu</code></strong> <em>(«FibexElement»)</em>:\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse aller Protocol Data Units.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>hasDynamicLength [0..1] : Boolean</code>: Gibt an, ob die PDU eine variable/dynamische Länge besitzt.\n</li><li><code>length [0..1] : Integer</code>: Statische oder maximale PDU-Länge in Byte.\n</li></ul>\n</li></ul>\n</li><li><strong><code>IPdu</code></strong>:\n<ul class=\"fig-list\"><li>Spezialisierung von <code>Pdu</code>. Repräsentiert Interaktionsschicht-PDUs.\n</li><li>Komposition: Hält <code>0..1</code> Instanz von <code>ContainedIPduProps</code> über die Rolle <code>+containedIPduProps</code>.\n</li></ul>\n</li><li><strong><code>ContainerIPdu</code></strong>:\n<ul class=\"fig-list\"><li>Spezialisierung von <code>IPdu</code>. Repräsentiert die aggregierende Hüll-PDU.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>containerTimeout [0..1] : TimeValue</code>: Maximales Wartefenster bis zum Zwangsversand unvollständig gefüllter Container.\n</li><li><code>containerTrigger [0..1] : ContainerIPduTriggerEnum</code>: Globales Auslöseverhalten für den Container.\n</li><li><code>headerType [1] : ContainerIPduHeaderTypeEnum</code>: Pflichtangabe zum Header-Format der eingebetteten PDUs.\n</li><li><code>minimumRxContainerQueueSize [0..1] : PositiveInteger</code>: Mindestgröße der empfangsseitigen Container-Warteschlange.\n</li><li><code>minimumTxContainerQueueSize [0..1] : PositiveInteger</code>: Mindestgröße der sendeseitigen Container-Warteschlange.\n</li><li><code>rxAcceptContainedIPdu [1] : RxAcceptContainedIPduEnum</code>: Filterstrategie bei der PDU-Extraktion auf Empfangsseite.\n</li><li><code>thresholdSize [0..1] : PositiveInteger</code>: Füllstandsschwelle in Bytes, bei deren Erreichen/Überschreiten der Container sofort ausgelöst wird.\n</li><li><code>unusedBitPattern [0..1] : PositiveInteger</code>: Bitmuster zum Auffüllen ungenutzter Bereiche im Container.\n</li></ul>\n</li></ul>\n</li><li><strong><code>ContainedIPduProps</code></strong>:\n<ul class=\"fig-list\"><li>Eigenschafts-Container für eingebettete I-PDUs innerhalb eines Containers.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>collectionSemantics [1] : ContainedIPduCollectionSemanticsEnum</code>: Update- und Pufferstrategie (<code>lastIsBest</code> vs. <code>queued</code>).\n</li><li><code>headerIdLongHeader [0..1] : PositiveInteger</code>: 32-Bit-ID bei Verwendung langer Header.\n</li><li><code>headerIdShortHeader [0..1] : PositiveInteger</code>: 24-Bit-ID bei Verwendung kurzer Header.\n</li><li><code>offset [0..1] : PositiveInteger</code>: Feste Byte-Offset-Position der Contained PDU innerhalb des Containers.\n</li><li><code>priority [0..1] : PositiveInteger</code>: Priorität der Contained PDU bei der Reihenfolge/Auswahl beim Packen.\n</li><li><code>timeout [0..1] : TimeValue</code>: Gültigkeits- bzw. Sammeltimeout der spezifischen Contained I-PDU.\n</li><li><code>trigger [0..1] : PduCollectionTriggerEnum</code>: Legt fest, ob das Eintreffen dieser PDU den Container-Versand initiiert.\n</li><li><code>updateIndicationBitPosition [0..1] : PositiveInteger</code>: Bitposition eines Update-Bits zur Erkennung neuer Daten.\n</li></ul>\n</li></ul>\n</li><li><strong><code>PduTriggering</code></strong> <em>(«Identifiable»)</em>:\n<ul class=\"fig-list\"><li>Abbildung einer PDU auf einen Kommunikationsport/Kanal.\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li>Assoziation verweist auf genau <code>1</code> <code>+iPdu</code> (<code>Pdu</code>).\n</li><li><code>1</code> <code>ContainerIPdu</code> aggregiert/referenziert <code>0..*</code> <code>+containedPduTriggering</code> (<code>PduTriggering</code>).\n</li></ul>\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Enumerationen</h5>\n<ul class=\"fig-list\"><li><strong><code>ContainerIPduHeaderTypeEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>shortHeader</code>: Kompakter Header (24 Bit Header-ID + 8 Bit Längenfeld = 4 Bytes Overhead; Nutzlast max. 255 Bytes je Contained PDU).\n</li><li><code>longHeader</code>: Erweiterter Header (32 Bit Header-ID + 32 Bit Längenfeld = 8 Bytes Overhead; für große PDUs/Ethernet).\n</li><li><code>noHeader</code>: Kein Header je Contained PDU (statische Platzierung über Offset).\n</li></ul>\n</li><li><strong><code>RxAcceptContainedIPduEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>acceptAll</code>: Akzeptiert alle im Stream empfangenen Contained-Header (auch unbekannte IDs werden akzeptiert/überlesen).\n</li><li><code>acceptConfigured</code>: Nur explizit im System konfigurierte Contained PDUs werden akzeptiert.\n</li></ul>\n</li><li><strong><code>PduCollectionTriggerEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>always</code>: Jedes Eintreffen dieser Contained I-PDU triggert sofort das Senden des Containers.\n</li><li><code>never</code>: Das Eintreffen dieser Contained I-PDU löst keinen sofortigen Sendevorgang aus (Versand erfolgt zeit- oder schwellwertbasiert).\n</li></ul>\n</li><li><strong><code>ContainerIPduTriggerEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>firstContainedTrigger</code>: Das Eintreffen der ersten Contained PDU startet das Container-Sammelzeitfenster.\n</li><li><code>defaultTrigger</code>: Standard-Triggerlogik für den Container.\n</li></ul>\n</li><li><strong><code>ContainedIPduCollectionSemanticsEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>lastIsBest</code>: Überschreibender Puffer; neuere Instanzen derselben PDU ersetzen ältere.\n</li><li><code>queued</code>: FIFO-Warteschlange; alle eingehenden Instanzen werden sequentiell gesammelt.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Sende-Pfad (TX-Aggregation / Packing)</h5>\n<ol class=\"fig-list\"><li><strong>PDU-Anlieferung:</strong> Eine obere Schicht (COM, SecOC, Dcm) übergibt eine I-PDU via <code>PduR_Transmit()</code> an die Routing Engine.\n</li><li><strong>Klassifikation &amp; Pufferung:</strong> \n<ul class=\"fig-list\"><li>Ist der Zielpfad eine <code>ContainerIPdu</code>, prüft das verarbeitende Modul (<code>PduR</code> / IPDU-Multiplexer) <code>ContainedIPduProps</code>.\n</li><li>Bei <code>collectionSemantics == lastIsBest</code> wird ein bestehender Eintrag im TX-Container-Puffer aktualisiert. Bei <code>queued</code> wird die PDU an das Ende des Aggregationspuffers angehängt.\n</li></ul>\n</li><li><strong>Serialisierung:</strong> Voranstellung des Headers (<code>shortHeader</code> oder <code>longHeader</code>) mit der konfigurierten <code>headerIdShortHeader</code> bzw. <code>headerIdLongHeader</code> und der tatsächlichen DLC/Länge.\n</li><li><strong>Trigger-Prüfung:</strong>\n<ul class=\"fig-list\"><li><strong>Sofort-Trigger:</strong> Falls <code>ContainedIPduProps.trigger == always</code> oder <code>ContainerIPduTriggerEnum == firstContainedTrigger</code>, wird die <code>ContainerIPdu</code> unmittelbar an das Interface (<code>CanIf</code>, <code>SoAd</code>) weitergegeben.\n</li><li><strong>Schwellwert-Trigger:</strong> Überschreitet die aggregierte Gesamtlänge <code>thresholdSize</code>, erfolgt sofortiger Push.\n</li><li><strong>Zeitbasierter Trigger:</strong> Läuft der asynchrone Hardware-/Software-Timer <code>containerTimeout</code> oder das PDU-individuelle <code>timeout</code> ab, wird die <code>ContainerIPdu</code> mit dem aktuellen Füllstand asynchron gesendet.\n</li></ul>\n</li></ol>\n<h5 class=\"fig-section-h5\">Empfangs-Pfad (RX-Disaggregation / Unpacking)</h5>\n<ol class=\"fig-list\"><li><strong>Container-Empfang:</strong> Die vollständige <code>ContainerIPdu</code> trifft über das untere Interface (<code>&lt;Bus&gt;If_RxIndication()</code>) im BSW-Stack ein.\n</li><li><strong>Header-Parsing:</strong> Der Byte-Stream wird sequentiell anhand des <code>headerType</code> geparst (Extraktion von ID und Längenfeld).\n</li><li><strong>Validierung &amp; Filterung:</strong>\n<ul class=\"fig-list\"><li>Stimmt die Header-ID mit einer bekannten <code>containedPduTriggering</code> überein, wird die Nutzlast extrahiert.\n</li><li>Ist die ID unbekannt: Bei <code>acceptConfigured</code> Abbruch bzw. PDU-Verwurf (ggf. Det-Meldung); bei <code>acceptAll</code> Weiterspringen um das Längenfeld zum nächsten Header.\n</li></ul>\n</li><li><strong>Dispatchen:</strong> Extrahierte Contained I-PDUs werden über <code>PduR_&lt;Target&gt;RxIndication()</code> an die jeweiligen Zielmodule verteilt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Konfiguration (<code>PduR</code> / CAN FD / Ethernet):</strong>\n<ul class=\"fig-list\"><li>Das Metamodell bildet 1:1 die Konfigurationscontainer <code>PduRContainerIPdu</code> und <code>PduRContainedIPdu</code> im BSW ab.\n</li><li><strong>Konsistenz-Restriktion:</strong> Wenn <code>headerType == shortHeader</code>, muss zwingend <code>headerIdShortHeader</code> gesetzt sein (Bereich: 1 bis 2^24-1). Bei <code>longHeader</code> ist <code>headerIdLongHeader</code> Pflicht (Bereich: 1 bis 2^32-1). Mischbetrieb innerhalb eines Containers ist verboten.\n</li></ul>\n</li><li><strong>Speicher- und Pufferallokation:</strong>\n<ul class=\"fig-list\"><li><code>collectionSemantics == queued</code> erzwingt im BSW-Generat statisch allokierte Ringpuffer (Multi-Element Queues). Entwickler müssen die maximale Queue-Tiefe gegen RAM-Verbrauch und Worst-Case-Latenz abgleichen.\n</li><li><code>lastIsBest</code> minimiert RAM-Overhead (Single-Buffer), führt bei langsamen Buszyklen jedoch zum unbemerkten Verwerfen älterer Datenstände (Data Overwrite).\n</li></ul>\n</li><li><strong>Echtzeit- und Latenz-Design:</strong>\n<ul class=\"fig-list\"><li>Zeitkritische I-PDUs (z. B. Brems-/Lenkanforderungen) müssen zwingend auf <code>trigger = always</code> konfiguriert werden, um ein Verzögern durch <code>containerTimeout</code> zu unterbinden.\n</li><li>Unbedachte Kombinationen von großem <code>thresholdSize</code> und fehlendem <code>containerTimeout</code> können bei unvollständigen Daten zum Blockieren/Verhungern (Starvation) von Contained I-PDUs im Puffer führen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-e636a31c8dabba57", "releases": ["R19-11", "R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt des AUTOSAR System Templates (<code>AUTOSAR_TPS_SystemTemplate</code>, PDU-Beschreibung im FIBEX-Modell, R4.2.2).\n</li><li><strong>Technischer Zweck:</strong> Modellierung des PDU-Multiplexings/Packings von mehreren logischen PDUs (<code>ContainedIPdu</code>) in einen gemeinsamen Transportrahmen (<code>ContainerIPdu</code>).\n</li><li><strong>Architektur-Einordnung:</strong> Dient als formale Entwurfsbasis für Kommunikationsstacks mit großen Frame-Kapazitäten (insbesondere CAN FD, FlexRay, Ethernet/SomeIP). Das Modell steuert im BSW-Stack (vor allem <code>PduR</code>, alternativ spezialisierte Module wie <code>IpduM</code>) das Packen, Puffern, Timen und Entpacken heterogener PDUs zur Bandbreitenoptimierung und Overhead-Reduktion.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metamodell-Klassen &amp; Vererbungen</h5>\n<ul class=\"fig-list\"><li><strong><code>Pdu</code></strong> <em>(«FibexElement»)</em>:\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse aller Protocol Data Units.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>hasDynamicLength [0..1] : Boolean</code>: Gibt an, ob die PDU eine variable/dynamische Länge besitzt.\n</li><li><code>length [0..1] : Integer</code>: Statische oder maximale PDU-Länge in Byte.\n</li></ul>\n</li></ul>\n</li><li><strong><code>IPdu</code></strong>:\n<ul class=\"fig-list\"><li>Spezialisierung von <code>Pdu</code>. Repräsentiert Interaktionsschicht-PDUs.\n</li><li>Komposition: Hält <code>0..1</code> Instanz von <code>ContainedIPduProps</code> über die Rolle <code>+containedIPduProps</code>.\n</li></ul>\n</li><li><strong><code>ContainerIPdu</code></strong>:\n<ul class=\"fig-list\"><li>Spezialisierung von <code>IPdu</code>. Repräsentiert die aggregierende Hüll-PDU.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>containerTimeout [0..1] : TimeValue</code>: Maximales Wartefenster bis zum Zwangsversand unvollständig gefüllter Container.\n</li><li><code>containerTrigger [0..1] : ContainerIPduTriggerEnum</code>: Globales Auslöseverhalten für den Container.\n</li><li><code>headerType [1] : ContainerIPduHeaderTypeEnum</code>: Pflichtangabe zum Header-Format der eingebetteten PDUs.\n</li><li><code>minimumRxContainerQueueSize [0..1] : PositiveInteger</code>: Mindestgröße der empfangsseitigen Container-Warteschlange.\n</li><li><code>minimumTxContainerQueueSize [0..1] : PositiveInteger</code>: Mindestgröße der sendeseitigen Container-Warteschlange.\n</li><li><code>rxAcceptContainedIPdu [1] : RxAcceptContainedIPduEnum</code>: Filterstrategie bei der PDU-Extraktion auf Empfangsseite.\n</li><li><code>thresholdSize [0..1] : PositiveInteger</code>: Füllstandsschwelle in Bytes, bei deren Erreichen/Überschreiten der Container sofort ausgelöst wird.\n</li><li><code>unusedBitPattern [0..1] : PositiveInteger</code>: Bitmuster zum Auffüllen ungenutzter Bereiche im Container.\n</li></ul>\n</li></ul>\n</li><li><strong><code>ContainedIPduProps</code></strong>:\n<ul class=\"fig-list\"><li>Eigenschafts-Container für eingebettete I-PDUs innerhalb eines Containers.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>collectionSemantics [1] : ContainedIPduCollectionSemanticsEnum</code>: Update- und Pufferstrategie (<code>lastIsBest</code> vs. <code>queued</code>).\n</li><li><code>headerIdLongHeader [0..1] : PositiveInteger</code>: 32-Bit-ID bei Verwendung langer Header.\n</li><li><code>headerIdShortHeader [0..1] : PositiveInteger</code>: 24-Bit-ID bei Verwendung kurzer Header.\n</li><li><code>offset [0..1] : PositiveInteger</code>: Feste Byte-Offset-Position der Contained PDU innerhalb des Containers.\n</li><li><code>priority [0..1] : PositiveInteger</code>: Priorität der Contained PDU bei der Reihenfolge/Auswahl beim Packen.\n</li><li><code>timeout [0..1] : TimeValue</code>: Gültigkeits- bzw. Sammeltimeout der spezifischen Contained I-PDU.\n</li><li><code>trigger [0..1] : PduCollectionTriggerEnum</code>: Legt fest, ob das Eintreffen dieser PDU den Container-Versand initiiert.\n</li><li><code>updateIndicationBitPosition [0..1] : PositiveInteger</code>: Bitposition eines Update-Bits zur Erkennung neuer Daten.\n</li></ul>\n</li></ul>\n</li><li><strong><code>PduTriggering</code></strong> <em>(«Identifiable»)</em>:\n<ul class=\"fig-list\"><li>Abbildung einer PDU auf einen Kommunikationsport/Kanal.\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li>Assoziation verweist auf genau <code>1</code> <code>+iPdu</code> (<code>Pdu</code>).\n</li><li><code>1</code> <code>ContainerIPdu</code> aggregiert/referenziert <code>0..*</code> <code>+containedPduTriggering</code> (<code>PduTriggering</code>).\n</li></ul>\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Enumerationen</h5>\n<ul class=\"fig-list\"><li><strong><code>ContainerIPduHeaderTypeEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>shortHeader</code>: Kompakter Header (24 Bit Header-ID + 8 Bit Längenfeld = 4 Bytes Overhead; Nutzlast max. 255 Bytes je Contained PDU).\n</li><li><code>longHeader</code>: Erweiterter Header (32 Bit Header-ID + 32 Bit Längenfeld = 8 Bytes Overhead; für große PDUs/Ethernet).\n</li><li><code>noHeader</code>: Kein Header je Contained PDU (statische Platzierung über Offset).\n</li></ul>\n</li><li><strong><code>RxAcceptContainedIPduEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>acceptAll</code>: Akzeptiert alle im Stream empfangenen Contained-Header (auch unbekannte IDs werden akzeptiert/überlesen).\n</li><li><code>acceptConfigured</code>: Nur explizit im System konfigurierte Contained PDUs werden akzeptiert.\n</li></ul>\n</li><li><strong><code>PduCollectionTriggerEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>always</code>: Jedes Eintreffen dieser Contained I-PDU triggert sofort das Senden des Containers.\n</li><li><code>never</code>: Das Eintreffen dieser Contained I-PDU löst keinen sofortigen Sendevorgang aus (Versand erfolgt zeit- oder schwellwertbasiert).\n</li></ul>\n</li><li><strong><code>ContainerIPduTriggerEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>firstContainedTrigger</code>: Das Eintreffen der ersten Contained PDU startet das Container-Sammelzeitfenster.\n</li><li><code>defaultTrigger</code>: Standard-Triggerlogik für den Container.\n</li></ul>\n</li><li><strong><code>ContainedIPduCollectionSemanticsEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>lastIsBest</code>: Überschreibender Puffer; neuere Instanzen derselben PDU ersetzen ältere.\n</li><li><code>queued</code>: FIFO-Warteschlange; alle eingehenden Instanzen werden sequentiell gesammelt.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Sende-Pfad (TX-Aggregation / Packing)</h5>\n<ol class=\"fig-list\"><li><strong>PDU-Anlieferung:</strong> Eine obere Schicht (COM, SecOC, Dcm) übergibt eine I-PDU via <code>PduR_Transmit()</code> an die Routing Engine.\n</li><li><strong>Klassifikation &amp; Pufferung:</strong> \n<ul class=\"fig-list\"><li>Ist der Zielpfad eine <code>ContainerIPdu</code>, prüft das verarbeitende Modul (<code>PduR</code> / IPDU-Multiplexer) <code>ContainedIPduProps</code>.\n</li><li>Bei <code>collectionSemantics == lastIsBest</code> wird ein bestehender Eintrag im TX-Container-Puffer aktualisiert. Bei <code>queued</code> wird die PDU an das Ende des Aggregationspuffers angehängt.\n</li></ul>\n</li><li><strong>Serialisierung:</strong> Voranstellung des Headers (<code>shortHeader</code> oder <code>longHeader</code>) mit der konfigurierten <code>headerIdShortHeader</code> bzw. <code>headerIdLongHeader</code> und der tatsächlichen DLC/Länge.\n</li><li><strong>Trigger-Prüfung:</strong>\n<ul class=\"fig-list\"><li><strong>Sofort-Trigger:</strong> Falls <code>ContainedIPduProps.trigger == always</code> oder <code>ContainerIPduTriggerEnum == firstContainedTrigger</code>, wird die <code>ContainerIPdu</code> unmittelbar an das Interface (<code>CanIf</code>, <code>SoAd</code>) weitergegeben.\n</li><li><strong>Schwellwert-Trigger:</strong> Überschreitet die aggregierte Gesamtlänge <code>thresholdSize</code>, erfolgt sofortiger Push.\n</li><li><strong>Zeitbasierter Trigger:</strong> Läuft der asynchrone Hardware-/Software-Timer <code>containerTimeout</code> oder das PDU-individuelle <code>timeout</code> ab, wird die <code>ContainerIPdu</code> mit dem aktuellen Füllstand asynchron gesendet.\n</li></ul>\n</li></ol>\n<h5 class=\"fig-section-h5\">Empfangs-Pfad (RX-Disaggregation / Unpacking)</h5>\n<ol class=\"fig-list\"><li><strong>Container-Empfang:</strong> Die vollständige <code>ContainerIPdu</code> trifft über das untere Interface (<code>&lt;Bus&gt;If_RxIndication()</code>) im BSW-Stack ein.\n</li><li><strong>Header-Parsing:</strong> Der Byte-Stream wird sequentiell anhand des <code>headerType</code> geparst (Extraktion von ID und Längenfeld).\n</li><li><strong>Validierung &amp; Filterung:</strong>\n<ul class=\"fig-list\"><li>Stimmt die Header-ID mit einer bekannten <code>containedPduTriggering</code> überein, wird die Nutzlast extrahiert.\n</li><li>Ist die ID unbekannt: Bei <code>acceptConfigured</code> Abbruch bzw. PDU-Verwurf (ggf. Det-Meldung); bei <code>acceptAll</code> Weiterspringen um das Längenfeld zum nächsten Header.\n</li></ul>\n</li><li><strong>Dispatchen:</strong> Extrahierte Contained I-PDUs werden über <code>PduR_&lt;Target&gt;RxIndication()</code> an die jeweiligen Zielmodule verteilt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Konfiguration (<code>PduR</code> / CAN FD / Ethernet):</strong>\n<ul class=\"fig-list\"><li>Das Metamodell bildet 1:1 die Konfigurationscontainer <code>PduRContainerIPdu</code> und <code>PduRContainedIPdu</code> im BSW ab.\n</li><li><strong>Konsistenz-Restriktion:</strong> Wenn <code>headerType == shortHeader</code>, muss zwingend <code>headerIdShortHeader</code> gesetzt sein (Bereich: 1 bis 2^24-1). Bei <code>longHeader</code> ist <code>headerIdLongHeader</code> Pflicht (Bereich: 1 bis 2^32-1). Mischbetrieb innerhalb eines Containers ist verboten.\n</li></ul>\n</li><li><strong>Speicher- und Pufferallokation:</strong>\n<ul class=\"fig-list\"><li><code>collectionSemantics == queued</code> erzwingt im BSW-Generat statisch allokierte Ringpuffer (Multi-Element Queues). Entwickler müssen die maximale Queue-Tiefe gegen RAM-Verbrauch und Worst-Case-Latenz abgleichen.\n</li><li><code>lastIsBest</code> minimiert RAM-Overhead (Single-Buffer), führt bei langsamen Buszyklen jedoch zum unbemerkten Verwerfen älterer Datenstände (Data Overwrite).\n</li></ul>\n</li><li><strong>Echtzeit- und Latenz-Design:</strong>\n<ul class=\"fig-list\"><li>Zeitkritische I-PDUs (z. B. Brems-/Lenkanforderungen) müssen zwingend auf <code>trigger = always</code> konfiguriert werden, um ein Verzögern durch <code>containerTimeout</code> zu unterbinden.\n</li><li>Unbedachte Kombinationen von großem <code>thresholdSize</code> und fehlendem <code>containerTimeout</code> können bei unvollständigen Daten zum Blockieren/Verhungern (Starvation) von Contained I-PDUs im Puffer führen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-8778e0babe527f2e", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt des AUTOSAR System Templates (<code>AUTOSAR_TPS_SystemTemplate</code>, PDU-Beschreibung im FIBEX-Modell, R4.2.2).\n</li><li><strong>Technischer Zweck:</strong> Modellierung des PDU-Multiplexings/Packings von mehreren logischen PDUs (<code>ContainedIPdu</code>) in einen gemeinsamen Transportrahmen (<code>ContainerIPdu</code>).\n</li><li><strong>Architektur-Einordnung:</strong> Dient als formale Entwurfsbasis für Kommunikationsstacks mit großen Frame-Kapazitäten (insbesondere CAN FD, FlexRay, Ethernet/SomeIP). Das Modell steuert im BSW-Stack (vor allem <code>PduR</code>, alternativ spezialisierte Module wie <code>IpduM</code>) das Packen, Puffern, Timen und Entpacken heterogener PDUs zur Bandbreitenoptimierung und Overhead-Reduktion.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metamodell-Klassen &amp; Vererbungen</h5>\n<ul class=\"fig-list\"><li><strong><code>Pdu</code></strong> <em>(«FibexElement»)</em>:\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse aller Protocol Data Units.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>hasDynamicLength [0..1] : Boolean</code>: Gibt an, ob die PDU eine variable/dynamische Länge besitzt.\n</li><li><code>length [0..1] : UnlimitedInteger</code>: Statische oder maximale PDU-Länge in Byte (unbegrenzter Wertebereich).\n</li></ul>\n</li></ul>\n</li><li><strong><code>IPdu</code></strong>:\n<ul class=\"fig-list\"><li>Spezialisierung von <code>Pdu</code>. Repräsentiert Interaktionsschicht-PDUs.\n</li><li>Komposition: Hält <code>0..1</code> Instanz von <code>ContainedIPduProps</code> über die Rolle <code>+containedIPduProps</code>.\n</li></ul>\n</li><li><strong><code>ContainerIPdu</code></strong>:\n<ul class=\"fig-list\"><li>Spezialisierung von <code>IPdu</code>. Repräsentiert die aggregierende Hüll-PDU.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>containerTimeout [0..1] : TimeValue</code>: Maximales Wartefenster bis zum Zwangsversand unvollständig gefüllter Container.\n</li><li><code>containerTrigger [0..1] : ContainerIPduTriggerEnum</code>: Globales Auslöseverhalten für den Container.\n</li><li><code>headerType [1] : ContainerIPduHeaderTypeEnum</code>: Pflichtangabe zum Header-Format der eingebetteten PDUs.\n</li><li><code>minimumRxContainerQueueSize [0..1] : PositiveInteger</code>: Mindestgröße der empfangsseitigen Container-Warteschlange.\n</li><li><code>minimumTxContainerQueueSize [0..1] : PositiveInteger</code>: Mindestgröße der sendeseitigen Container-Warteschlange.\n</li><li><code>rxAcceptContainedIPdu [1] : RxAcceptContainedIPduEnum</code>: Filterstrategie bei der PDU-Extraktion auf Empfangsseite.\n</li><li><code>thresholdSize [0..1] : PositiveInteger</code>: Füllstandsschwelle in Bytes, bei deren Erreichen/Überschreiten der Container sofort ausgelöst wird.\n</li><li><code>unusedBitPattern [0..1] : PositiveInteger</code>: Bitmuster zum Auffüllen ungenutzter Bereiche im Container.\n</li></ul>\n</li><li>Assoziationen &amp; Kompositionen:\n<ul class=\"fig-list\"><li>Hält <code>0..*</code> <code>+containedPduTriggering</code> (<code>PduTriggering</code>).\n</li><li>Komposition: Hält <code>0..*</code> Instanzen von <code>ContainedIPduProps</code> über die Rolle <code>+containedIPduTriggeringProps</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>ContainedIPduProps</code></strong>:\n<ul class=\"fig-list\"><li>Eigenschafts-Container für eingebettete I-PDUs innerhalb eines Containers.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>collectionSemantics [1] : ContainedIPduCollectionSemanticsEnum</code>: Update- und Pufferstrategie (<code>lastIsBest</code> vs. <code>queued</code>).\n</li><li><code>headerIdLongHeader [0..1] : PositiveInteger</code>: 32-Bit-ID bei Verwendung langer Header.\n</li><li><code>headerIdShortHeader [0..1] : PositiveInteger</code>: 24-Bit-ID bei Verwendung kurzer Header.\n</li><li><code>offset [0..1] : PositiveInteger</code>: Feste Byte-Offset-Position der Contained PDU innerhalb des Containers.\n</li><li><code>priority [0..1] : PositiveInteger</code>: Priorität der Contained PDU bei der Reihenfolge/Auswahl beim Packen.\n</li><li><code>timeout [0..1] : TimeValue</code>: Gültigkeits- bzw. Sammeltimeout der spezifischen Contained I-PDU.\n</li><li><code>trigger [0..1] : PduCollectionTriggerEnum</code>: Legt fest, ob das Eintreffen dieser PDU den Container-Versand initiiert.\n</li><li><code>updateIndicationBitPosition [0..1] : PositiveInteger</code>: Bitposition eines Update-Bits zur Erkennung neuer Daten.\n</li></ul>\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li>Referenziert <code>0..1</code> <code>+containedPduTriggering</code> (<code>PduTriggering</code>).\n</li></ul>\n</li></ul>\n</li><li><strong><code>PduTriggering</code></strong> <em>(«Identifiable»)</em>:\n<ul class=\"fig-list\"><li>Abbildung einer PDU auf einen Kommunikationsport/Kanal.\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li>Assoziation verweist auf genau <code>1</code> <code>+iPdu</code> (<code>Pdu</code>).\n</li><li>Aggregiert/referenziert durch <code>ContainerIPdu</code> (<code>+containedPduTriggering 0..*</code>).\n</li><li>Assoziiert durch <code>ContainedIPduProps</code> (<code>+containedPduTriggering 0..1</code>).\n</li></ul>\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Enumerationen</h5>\n<ul class=\"fig-list\"><li><strong><code>ContainerIPduHeaderTypeEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>shortHeader</code>: Kompakter Header (24 Bit Header-ID + 8 Bit Längenfeld = 4 Bytes Overhead; Nutzlast max. 255 Bytes je Contained PDU).\n</li><li><code>longHeader</code>: Erweiterter Header (32 Bit Header-ID + 32 Bit Längenfeld = 8 Bytes Overhead; für große PDUs/Ethernet).\n</li><li><code>noHeader</code>: Kein Header je Contained PDU (statische Platzierung über Offset).\n</li></ul>\n</li><li><strong><code>RxAcceptContainedIPduEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>acceptAll</code>: Akzeptiert alle im Stream empfangenen Contained-Header (auch unbekannte IDs werden akzeptiert/überlesen).\n</li><li><code>acceptConfigured</code>: Nur explizit im System konfigurierte Contained PDUs werden akzeptiert.\n</li></ul>\n</li><li><strong><code>PduCollectionTriggerEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>always</code>: Jedes Eintreffen dieser Contained I-PDU triggert sofort das Senden des Containers.\n</li><li><code>never</code>: Das Eintreffen dieser Contained I-PDU löst keinen sofortigen Sendevorgang aus (Versand erfolgt zeit- oder schwellwertbasiert).\n</li></ul>\n</li><li><strong><code>ContainerIPduTriggerEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>firstContainedTrigger</code>: Das Eintreffen der ersten Contained PDU startet das Container-Sammelzeitfenster.\n</li><li><code>defaultTrigger</code>: Standard-Triggerlogik für den Container.\n</li></ul>\n</li><li><strong><code>ContainedIPduCollectionSemanticsEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>lastIsBest</code>: Überschreibender Puffer; neuere Instanzen derselben PDU ersetzen ältere.\n</li><li><code>queued</code>: FIFO-Warteschlange; alle eingehenden Instanzen werden sequentiell gesammelt.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Sende-Pfad (TX-Aggregation / Packing)</h5>\n<ol class=\"fig-list\"><li><strong>PDU-Anlieferung:</strong> Eine obere Schicht (COM, SecOC, Dcm) übergibt eine I-PDU via <code>PduR_Transmit()</code> an die Routing Engine.\n</li><li><strong>Klassifikation &amp; Pufferung:</strong> \n<ul class=\"fig-list\"><li>Ist der Zielpfad eine <code>ContainerIPdu</code>, prüft das verarbeitende Modul (<code>PduR</code> / IPDU-Multiplexer) <code>ContainedIPduProps</code>.\n</li><li>Bei <code>collectionSemantics == lastIsBest</code> wird ein bestehender Eintrag im TX-Container-Puffer aktualisiert. Bei <code>queued</code> wird die PDU an das Ende des Aggregationspuffers angehängt.\n</li></ul>\n</li><li><strong>Serialisierung:</strong> Voranstellung des Headers (<code>shortHeader</code> oder <code>longHeader</code>) mit der konfigurierten <code>headerIdShortHeader</code> bzw. <code>headerIdLongHeader</code> und der tatsächlichen DLC/Länge.\n</li><li><strong>Trigger-Prüfung:</strong>\n<ul class=\"fig-list\"><li><strong>Sofort-Trigger:</strong> Falls <code>ContainedIPduProps.trigger == always</code> oder <code>ContainerIPduTriggerEnum == firstContainedTrigger</code>, wird die <code>ContainerIPdu</code> unmittelbar an das Interface (<code>CanIf</code>, <code>SoAd</code>) weitergegeben.\n</li><li><strong>Schwellwert-Trigger:</strong> Überschreitet die aggregierte Gesamtlänge <code>thresholdSize</code>, erfolgt sofortiger Push.\n</li><li><strong>Zeitbasierter Trigger:</strong> Läuft der asynchrone Hardware-/Software-Timer <code>containerTimeout</code> oder das PDU-individuelle <code>timeout</code> ab, wird die <code>ContainerIPdu</code> mit dem aktuellen Füllstand asynchron gesendet.\n</li></ul>\n</li></ol>\n<h5 class=\"fig-section-h5\">Empfangs-Pfad (RX-Disaggregation / Unpacking)</h5>\n<ol class=\"fig-list\"><li><strong>Container-Empfang:</strong> Die vollständige <code>ContainerIPdu</code> trifft über das untere Interface (<code>&lt;Bus&gt;If_RxIndication()</code>) im BSW-Stack ein.\n</li><li><strong>Header-Parsing:</strong> Der Byte-Stream wird sequentiell anhand des <code>headerType</code> geparst (Extraktion von ID und Längenfeld).\n</li><li><strong>Validierung &amp; Filterung:</strong>\n<ul class=\"fig-list\"><li>Stimmt die Header-ID mit einer bekannten <code>containedPduTriggering</code> überein, wird die Nutzlast extrahiert.\n</li><li>Ist die ID unbekannt: Bei <code>acceptConfigured</code> Abbruch bzw. PDU-Verwurf (ggf. Det-Meldung); bei <code>acceptAll</code> Weiterspringen um das Längenfeld zum nächsten Header.\n</li></ul>\n</li><li><strong>Dispatchen:</strong> Extrahierte Contained I-PDUs werden über <code>PduR_&lt;Target&gt;RxIndication()</code> an die jeweiligen Zielmodule verteilt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Konfiguration (<code>PduR</code> / CAN FD / Ethernet):</strong>\n<ul class=\"fig-list\"><li>Das Metamodell bildet 1:1 die Konfigurationscontainer <code>PduRContainerIPdu</code> und <code>PduRContainedIPdu</code> im BSW ab.\n</li><li><strong>Konsistenz-Restriktion:</strong> Wenn <code>headerType == shortHeader</code>, muss zwingend <code>headerIdShortHeader</code> gesetzt sein (Bereich: 1 bis 2^24-1). Bei <code>longHeader</code> ist <code>headerIdLongHeader</code> Pflicht (Bereich: 1 bis 2^32-1). Mischbetrieb innerhalb eines Containers ist verboten.\n</li></ul>\n</li><li><strong>Speicher- und Pufferallokation:</strong>\n<ul class=\"fig-list\"><li><code>collectionSemantics == queued</code> erzwingt im BSW-Generat statisch allokierte Ringpuffer (Multi-Element Queues). Entwickler müssen die maximale Queue-Tiefe gegen RAM-Verbrauch und Worst-Case-Latenz abgleichen.\n</li><li><code>lastIsBest</code> minimiert RAM-Overhead (Single-Buffer), führt bei langsamen Buszyklen jedoch zum unbemerkten Verwerfen älterer Datenstände (Data Overwrite).\n</li></ul>\n</li><li><strong>Echtzeit- und Latenz-Design:</strong>\n<ul class=\"fig-list\"><li>Zeitkritische I-PDUs (z. B. Brems-/Lenkanforderungen) müssen zwingend auf <code>trigger = always</code> konfiguriert werden, um ein Verzögern durch <code>containerTimeout</code> zu unterbinden.\n</li><li>Unbedachte Kombinationen von großem <code>thresholdSize</code> und fehlendem <code>containerTimeout</code> können bei unvollständigen Daten zum Blockieren/Verhungern (Starvation) von Contained I-PDUs im Puffer führen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-1d9f5110ae350f17", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt des AUTOSAR System Templates (<code>AUTOSAR_TPS_SystemTemplate</code>, PDU-Beschreibung im FIBEX-Modell, R4.2.2).\n</li><li><strong>Technischer Zweck:</strong> Modellierung des PDU-Multiplexings/Packings von mehreren logischen PDUs (<code>ContainedIPdu</code>) in einen gemeinsamen Transportrahmen (<code>ContainerIPdu</code>).\n</li><li><strong>Architektur-Einordnung:</strong> Dient als formale Entwurfsbasis für Kommunikationsstacks mit großen Frame-Kapazitäten (insbesondere CAN FD, FlexRay, Ethernet/SomeIP). Das Modell steuert im BSW-Stack (vor allem <code>PduR</code>, alternativ spezialisierte Module wie <code>IpduM</code>) das Packen, Puffern, Timen und Entpacken heterogener PDUs zur Bandbreitenoptimierung und Overhead-Reduktion.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metamodell-Klassen &amp; Vererbungen</h5>\n<ul class=\"fig-list\"><li><strong><code>Pdu</code></strong> <em>(«FibexElement, UploadableDesignElement»)</em>:\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse aller Protocol Data Units und ladbares Designelement.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>hasDynamicLength [0..1] : Boolean</code>: Gibt an, ob die PDU eine variable/dynamische Länge besitzt.\n</li><li><code>length [0..1] : UnlimitedInteger</code>: Statische oder maximale PDU-Länge in Byte (unbegrenzter Wertebereich).\n</li></ul>\n</li></ul>\n</li><li><strong><code>IPdu</code></strong>:\n<ul class=\"fig-list\"><li>Spezialisierung von <code>Pdu</code>. Repräsentiert Interaktionsschicht-PDUs.\n</li><li>Komposition: Hält <code>0..1</code> Instanz von <code>ContainedIPduProps</code> über die Rolle <code>+containedIPduProps</code>.\n</li></ul>\n</li><li><strong><code>ContainerIPdu</code></strong>:\n<ul class=\"fig-list\"><li>Spezialisierung von <code>IPdu</code>. Repräsentiert die aggregierende Hüll-PDU.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>containerTimeout [0..1] : TimeValue</code>: Maximales Wartefenster bis zum Zwangsversand unvollständig gefüllter Container.\n</li><li><code>containerTrigger [0..1] : ContainerIPduTriggerEnum</code>: Globales Auslöseverhalten für den Container.\n</li><li><code>headerType [0..1] : ContainerIPduHeaderTypeEnum</code>: Header-Format der eingebetteten PDUs.\n</li><li><code>minimumRxContainerQueueSize [0..1] : PositiveInteger</code>: Mindestgröße der empfangsseitigen Container-Warteschlange.\n</li><li><code>minimumTxContainerQueueSize [0..1] : PositiveInteger</code>: Mindestgröße der sendeseitigen Container-Warteschlange.\n</li><li><code>rxAcceptContainedIPdu [0..1] : RxAcceptContainedIPduEnum</code>: Filterstrategie bei der PDU-Extraktion auf Empfangsseite.\n</li><li><code>thresholdSize [0..1] : PositiveInteger</code>: Füllstandsschwelle in Bytes, bei deren Erreichen/Überschreiten der Container sofort ausgelöst wird.\n</li><li><code>unusedBitPattern [0..1] : PositiveInteger</code>: Bitmuster zum Auffüllen ungenutzter Bereiche im Container.\n</li></ul>\n</li><li>Assoziationen &amp; Kompositionen:\n<ul class=\"fig-list\"><li>Hält <code>0..*</code> <code>+containedPduTriggering</code> (<code>PduTriggering</code>).\n</li><li>Komposition: Hält <code>0..*</code> Instanzen von <code>ContainedIPduProps</code> über die Rolle <code>+containedIPduTriggeringProps</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>ContainedIPduProps</code></strong>:\n<ul class=\"fig-list\"><li>Eigenschafts-Container für eingebettete I-PDUs innerhalb eines Containers.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>collectionSemantics [0..1] : ContainedIPduCollectionSemanticsEnum</code>: Update- und Pufferstrategie (<code>lastIsBest</code> vs. <code>queued</code>).\n</li><li><code>headerIdLongHeader [0..1] : PositiveInteger</code>: 32-Bit-ID bei Verwendung langer Header.\n</li><li><code>headerIdShortHeader [0..1] : PositiveInteger</code>: 24-Bit-ID bei Verwendung kurzer Header.\n</li><li><code>offset [0..1] : PositiveInteger</code>: Feste Byte-Offset-Position der Contained PDU innerhalb des Containers.\n</li><li><code>priority [0..1] : PositiveInteger</code>: Priorität der Contained PDU bei der Reihenfolge/Auswahl beim Packen.\n</li><li><code>timeout [0..1] : TimeValue</code>: Gültigkeits- bzw. Sammeltimeout der spezifischen Contained I-PDU.\n</li><li><code>trigger [0..1] : PduCollectionTriggerEnum</code>: Legt fest, ob das Eintreffen dieser PDU den Container-Versand initiiert.\n</li><li><code>updateIndicationBitPosition [0..1] : PositiveInteger</code>: Bitposition eines Update-Bits zur Erkennung neuer Daten.\n</li></ul>\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li>Referenziert <code>0..1</code> <code>+containedPduTriggering</code> (<code>PduTriggering</code>).\n</li></ul>\n</li></ul>\n</li><li><strong><code>PduTriggering</code></strong> <em>(«Identifiable»)</em>:\n<ul class=\"fig-list\"><li>Abbildung einer PDU auf einen Kommunikationsport/Kanal.\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li>Assoziation verweist auf <code>0..1</code> <code>+iPdu</code> (<code>Pdu</code>).\n</li><li>Aggregiert/referenziert durch <code>ContainerIPdu</code> (<code>+containedPduTriggering 0..*</code>).\n</li><li>Assoziiert durch <code>ContainedIPduProps</code> (<code>+containedPduTriggering 0..1</code>).\n</li></ul>\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Enumerationen</h5>\n<ul class=\"fig-list\"><li><strong><code>ContainerIPduHeaderTypeEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>shortHeader</code>: Kompakter Header (24 Bit Header-ID + 8 Bit Längenfeld = 4 Bytes Overhead; Nutzlast max. 255 Bytes je Contained PDU).\n</li><li><code>longHeader</code>: Erweiterter Header (32 Bit Header-ID + 32 Bit Längenfeld = 8 Bytes Overhead; für große PDUs/Ethernet).\n</li><li><code>noHeader</code>: Kein Header je Contained PDU (statische Platzierung über Offset).\n</li></ul>\n</li><li><strong><code>RxAcceptContainedIPduEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>acceptAll</code>: Akzeptiert alle im Stream empfangenen Contained-Header (auch unbekannte IDs werden akzeptiert/überlesen).\n</li><li><code>acceptConfigured</code>: Nur explizit im System konfigurierte Contained PDUs werden akzeptiert.\n</li></ul>\n</li><li><strong><code>PduCollectionTriggerEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>always</code>: Jedes Eintreffen dieser Contained I-PDU triggert sofort das Senden des Containers.\n</li><li><code>never</code>: Das Eintreffen dieser Contained I-PDU löst keinen sofortigen Sendevorgang aus (Versand erfolgt zeit- oder schwellwertbasiert).\n</li></ul>\n</li><li><strong><code>ContainerIPduTriggerEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>firstContainedTrigger</code>: Das Eintreffen der ersten Contained PDU startet das Container-Sammelzeitfenster.\n</li><li><code>defaultTrigger</code>: Standard-Triggerlogik für den Container.\n</li></ul>\n</li><li><strong><code>ContainedIPduCollectionSemanticsEnum</code></strong>:\n<ul class=\"fig-list\"><li><code>lastIsBest</code>: Überschreibender Puffer; neuere Instanzen derselben PDU ersetzen ältere.\n</li><li><code>queued</code>: FIFO-Warteschlange; alle eingehenden Instanzen werden sequentiell gesammelt.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Sende-Pfad (TX-Aggregation / Packing)</h5>\n<ol class=\"fig-list\"><li><strong>PDU-Anlieferung:</strong> Eine obere Schicht (COM, SecOC, Dcm) übergibt eine I-PDU via <code>PduR_Transmit()</code> an die Routing Engine.\n</li><li><strong>Klassifikation &amp; Pufferung:</strong> \n<ul class=\"fig-list\"><li>Ist der Zielpfad eine <code>ContainerIPdu</code>, prüft das verarbeitende Modul (<code>PduR</code> / IPDU-Multiplexer) <code>ContainedIPduProps</code>.\n</li><li>Bei <code>collectionSemantics == lastIsBest</code> wird ein bestehender Eintrag im TX-Container-Puffer aktualisiert. Bei <code>queued</code> wird die PDU an das Ende des Aggregationspuffers angehängt.\n</li></ul>\n</li><li><strong>Serialisierung:</strong> Voranstellung des Headers (<code>shortHeader</code> oder <code>longHeader</code>) mit der konfigurierten <code>headerIdShortHeader</code> bzw. <code>headerIdLongHeader</code> und der tatsächlichen DLC/Länge.\n</li><li><strong>Trigger-Prüfung:</strong>\n<ul class=\"fig-list\"><li><strong>Sofort-Trigger:</strong> Falls <code>ContainedIPduProps.trigger == always</code> oder <code>ContainerIPduTriggerEnum == firstContainedTrigger</code>, wird die <code>ContainerIPdu</code> unmittelbar an das Interface (<code>CanIf</code>, <code>SoAd</code>) weitergegeben.\n</li><li><strong>Schwellwert-Trigger:</strong> Überschreitet die aggregierte Gesamtlänge <code>thresholdSize</code>, erfolgt sofortiger Push.\n</li><li><strong>Zeitbasierter Trigger:</strong> Läuft der asynchrone Hardware-/Software-Timer <code>containerTimeout</code> oder das PDU-individuelle <code>timeout</code> ab, wird die <code>ContainerIPdu</code> mit dem aktuellen Füllstand asynchron gesendet.\n</li></ul>\n</li></ol>\n<h5 class=\"fig-section-h5\">Empfangs-Pfad (RX-Disaggregation / Unpacking)</h5>\n<ol class=\"fig-list\"><li><strong>Container-Empfang:</strong> Die vollständige <code>ContainerIPdu</code> trifft über das untere Interface (<code>&lt;Bus&gt;If_RxIndication()</code>) im BSW-Stack ein.\n</li><li><strong>Header-Parsing:</strong> Der Byte-Stream wird sequentiell anhand des <code>headerType</code> geparst (Extraktion von ID und Längenfeld).\n</li><li><strong>Validierung &amp; Filterung:</strong>\n<ul class=\"fig-list\"><li>Stimmt die Header-ID mit einer bekannten <code>containedPduTriggering</code> überein, wird die Nutzlast extrahiert.\n</li><li>Ist die ID unbekannt: Bei <code>acceptConfigured</code> Abbruch bzw. PDU-Verwurf (ggf. Det-Meldung); bei <code>acceptAll</code> Weiterspringen um das Längenfeld zum nächsten Header.\n</li></ul>\n</li><li><strong>Dispatchen:</strong> Extrahierte Contained I-PDUs werden über <code>PduR_&lt;Target&gt;RxIndication()</code> an die jeweiligen Zielmodule verteilt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Konfiguration (<code>PduR</code> / CAN FD / Ethernet):</strong>\n<ul class=\"fig-list\"><li>Das Metamodell bildet 1:1 die Konfigurationscontainer <code>PduRContainerIPdu</code> und <code>PduRContainedIPdu</code> im BSW ab.\n</li><li><strong>Konsistenz-Restriktion:</strong> Wenn <code>headerType == shortHeader</code>, muss zwingend <code>headerIdShortHeader</code> gesetzt sein (Bereich: 1 bis 2^24-1). Bei <code>longHeader</code> ist <code>headerIdLongHeader</code> Pflicht (Bereich: 1 bis 2^32-1). Mischbetrieb innerhalb eines Containers ist verboten.\n</li></ul>\n</li><li><strong>Speicher- und Pufferallokation:</strong>\n<ul class=\"fig-list\"><li><code>collectionSemantics == queued</code> erzwingt im BSW-Generat statisch allokierte Ringpuffer (Multi-Element Queues). Entwickler müssen die maximale Queue-Tiefe gegen RAM-Verbrauch und Worst-Case-Latenz abgleichen.\n</li><li><code>lastIsBest</code> minimiert RAM-Overhead (Single-Buffer), führt bei langsamen Buszyklen jedoch zum unbemerkten Verwerfen älterer Datenstände (Data Overwrite).\n</li></ul>\n</li><li><strong>Echtzeit- und Latenz-Design:</strong>\n<ul class=\"fig-list\"><li>Zeitkritische I-PDUs (z. B. Brems-/Lenkanforderungen) müssen zwingend auf <code>trigger = always</code> konfiguriert werden, um ein Verzögern durch <code>containerTimeout</code> zu unterbinden.\n</li><li>Unbedachte Kombinationen von großem <code>thresholdSize</code> und fehlendem <code>containerTimeout</code> können bei unvollständigen Daten zum Blockieren/Verhungern (Starvation) von Contained I-PDUs im Puffer führen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-982ca8cec76fad31", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt des AUTOSAR System Templates (<code>AUTOSAR_TPS_SystemTemplate</code>, PDU-Beschreibung im FIBEX-Modell, R4.2.2).\n</li><li><strong>Technischer Zweck:</strong> Modellierung des PDU-Multiplexings/Packings von mehreren logischen PDUs (<code>ContainedIPdu</code>) in einen gemeinsamen Transportrahmen (<code>ContainerIPdu</code>).\n</li><li><strong>Architektur-Einordnung:</strong> Dient als formale Entwurfsbasis für Kommunikationsstacks mit großen Frame-Kapazitäten (insbesondere CAN FD, FlexRay, Ethernet/SomeIP). Das Modell steuert im BSW-Stack (vor allem <code>PduR</code>, alternativ spezialisierte Module wie <code>IpduM</code>) das Packen, Puffern, Timen und Entpacken heterogener PDUs zur Bandbreitenoptimierung und Overhead-Reduktion.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metamodell-Klassen &amp; Vererbungen</h5>\n<ul class=\"fig-list\"><li><strong><code>Pdu</code></strong> <em>(«FibexElement, UploadableDesignElement»)</em>:\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse aller Protocol Data Units und ladbares Designelement.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>hasDynamicLength [0..1] : Boolean</code>: Gibt an, ob die PDU eine variable/dynamische Länge besitzt.\n</li><li><code>length [0..1] : UnlimitedInteger</code>: Statische oder maximale PDU-Länge in Byte (unbegrenzter Wertebereich).\n</li></ul>\n</li></ul>\n</li><li><strong><code>IPdu</code></strong>:\n<ul class=\"fig-list\"><li>Spezialisierung von <code>Pdu</code>. Repräsentiert Interaktionsschicht-PDUs.\n</li><li>Komposition: Hält <code>0..1</code> Instanz von <code>ContainedIPduProps</code> über die Rolle <code>+containedIPduProps</code>.\n</li></ul>\n</li><li><strong><code>ContainerIPdu</code></strong>:\n<ul class=\"fig-list\"><li>Spezialisierung von <code>IPdu</code>. Repräsentiert die aggregierende Hüll-PDU.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>containerTimeout [0..1] : TimeValue</code>: Maximales Wartefenster bis zum Zwangsversand unvollständig gefüllter Container.\n</li><li><code>containerTrigger [0..1] : ContainerIPduTriggerEnum</code>: Globales Auslöseverhalten für den Container.\n</li><li><code>headerType [0..1] : ContainerIPduHeaderTypeEnum</code>: Header-Format der eingebetteten PDUs.\n</li><li><code>minimumRxContainerQueueSize [0..1] : PositiveInteger</code>: Mindestgröße der empfangsseitigen Container-Warteschlange.\n</li><li><code>minimumTxContainerQueueSize [0..1] : PositiveInteger</code>: Mindestgröße der sendeseitigen Container-Warteschlange.\n</li><li><code>rxAcceptContainedIPdu [0..1] : RxAcceptContainedIPduEnum</code>: Filterstrategie bei der PDU-Extraktion auf Empfangsseite.\n</li><li><code>thresholdSize [0..1] : PositiveInteger</code>: Füllstandsschwelle in Bytes, bei deren Erreichen/Überschreiten der Container sofort ausgelöst wird.\n</li><li><code>unusedBitPattern [0..1] : PositiveInteger</code>: Bitmuster zum Auffüllen ungenutzter Bereiche im Container.\n</li></ul>\n</li><li>Assoziationen &amp; Kompositionen:\n<ul class=\"fig-list\"><li>Hält <code>0..*</code> <code>+containedPduTriggering</code> (<code>PduTriggering</code>).\n</li><li>Komposition: Hält <code>0..*</code> Instanzen von <code>ContainedIPduProps</code> über die Rolle <code>+containedIPduTriggeringProps</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>ContainedIPduProps</code></strong>:\n<ul class=\"fig-list\"><li>Eigenschafts-Container für eingebettete I-PDUs innerhalb eines Containers.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>collectionSemantics [0..1] : ContainedIPduCollectionSemanticsEnum</code>: Update- und Pufferstrategie (<code>lastIsBest</code> vs. <code>queued</code>).\n</li><li><code>headerIdLongHeader [0..1] : PositiveInteger</code>: 32-Bit-ID bei Verwendung langer Header.\n</li><li><code>headerIdShortHeader [0..1] : PositiveInteger</code>: 24-Bit-ID bei Verwendung kurzer Header.\n</li><li><code>offset [0..1] : PositiveInteger</code>: Feste Byte-Offset-Position der Contained PDU innerhalb des Containers.\n</li><li><code>priority [0..1] : PositiveInteger</code>: Priorität der Contained PDU bei der Reihenfolge/Auswahl beim Packen.\n</li><li><code>timeout [0..1] : TimeValue</code>: Gültigkeits- bzw. Sammeltimeout der spezifischen Contained I-PDU.\n</li><li><code>trigger [0..1] : PduCollectionTriggerEnum</code>: Legt fest, ob das Eintreffen dieser PDU den Container-Versand initiiert.\n</li><li><code>updateIndicationBitPosition [0..1] : PositiveInteger</code>: Bitposition eines Update-Bits zur Erkennung neuer Daten.\n</li></ul>\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li>Referenziert <code>0..1</code> <code>+containedPduTriggering</code> (<code>PduTriggering</code>).\n</li></ul>\n</li></ul>\n</li><li><strong><code>PduTriggering</code></strong> <em>(«Identifiable»)</em>:\n<ul class=\"fig-list\"><li>Abbildung einer PDU auf einen Kommunikationsport/Kanal.\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li>Assoziation verweist auf <code>0..1</code> <code>+iPdu</code> (<code>Pdu</code>).\n</li><li>Aggregiert/referenziert durch <code>ContainerIPdu</code> (<code>+containedPduTriggering 0..*</code>).\n</li><li>Assoziiert durch <code>ContainedIPduProps</code> (<code>+containedPduTriggering 0..1</code>).\n</li></ul>\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Enumerationen</h5>\n<ul class=\"fig-list\"><li><strong><code>ContainerIPduHeaderTypeEnum</code></strong>:\n<ul class=\"fig-list\"><li>literals:\n<ul class=\"fig-list\"><li><code>shortHeader</code>: Kompakter Header (24 Bit Header-ID + 8 Bit Längenfeld = 4 Bytes Overhead; Nutzlast max. 255 Bytes je Contained PDU).\n</li><li><code>longHeader</code>: Erweiterter Header (32 Bit Header-ID + 32 Bit Längenfeld = 8 Bytes Overhead; für große PDUs/Ethernet).\n</li><li><code>noHeader</code>: Kein Header je Contained PDU (statische Platzierung über Offset).\n</li></ul>\n</li></ul>\n</li><li><strong><code>RxAcceptContainedIPduEnum</code></strong>:\n<ul class=\"fig-list\"><li>literals:\n<ul class=\"fig-list\"><li><code>acceptAll</code>: Akzeptiert alle im Stream empfangenen Contained-Header (auch unbekannte IDs werden akzeptiert/überlesen).\n</li><li><code>acceptConfigured</code>: Nur explizit im System konfigurierte Contained PDUs werden akzeptiert.\n</li></ul>\n</li></ul>\n</li><li><strong><code>PduCollectionTriggerEnum</code></strong>:\n<ul class=\"fig-list\"><li>literals:\n<ul class=\"fig-list\"><li><code>always</code>: Jedes Eintreffen dieser Contained I-PDU triggert sofort das Senden des Containers.\n</li><li><code>never</code>: Das Eintreffen dieser Contained I-PDU löst keinen sofortigen Sendevorgang aus (Versand erfolgt zeit- oder schwellwertbasiert).\n</li></ul>\n</li></ul>\n</li><li><strong><code>ContainerIPduTriggerEnum</code></strong>:\n<ul class=\"fig-list\"><li>literals:\n<ul class=\"fig-list\"><li><code>firstContainedTrigger</code>: Das Eintreffen der ersten Contained PDU startet das Container-Sammelzeitfenster.\n</li><li><code>defaultTrigger</code>: Standard-Triggerlogik für den Container.\n</li></ul>\n</li></ul>\n</li><li><strong><code>ContainedIPduCollectionSemanticsEnum</code></strong>:\n<ul class=\"fig-list\"><li>literals:\n<ul class=\"fig-list\"><li><code>lastIsBest</code>: Überschreibender Puffer; neuere Instanzen derselben PDU ersetzen ältere.\n</li><li><code>queued</code>: FIFO-Warteschlange; alle eingehenden Instanzen werden sequentiell gesammelt.\n</li></ul>\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Sende-Pfad (TX-Aggregation / Packing)</h5>\n<ol class=\"fig-list\"><li><strong>PDU-Anlieferung:</strong> Eine obere Schicht (COM, SecOC, Dcm) übergibt eine I-PDU via <code>PduR_Transmit()</code> an die Routing Engine.\n</li><li><strong>Klassifikation &amp; Pufferung:</strong> \n<ul class=\"fig-list\"><li>Ist der Zielpfad eine <code>ContainerIPdu</code>, prüft das verarbeitende Modul (<code>PduR</code> / IPDU-Multiplexer) <code>ContainedIPduProps</code>.\n</li><li>Bei <code>collectionSemantics == lastIsBest</code> wird ein bestehender Eintrag im TX-Container-Puffer aktualisiert. Bei <code>queued</code> wird die PDU an das Ende des Aggregationspuffers angehängt.\n</li></ul>\n</li><li><strong>Serialisierung:</strong> Voranstellung des Headers (<code>shortHeader</code> oder <code>longHeader</code>) mit der konfigurierten <code>headerIdShortHeader</code> bzw. <code>headerIdLongHeader</code> und der tatsächlichen DLC/Länge.\n</li><li><strong>Trigger-Prüfung:</strong>\n<ul class=\"fig-list\"><li><strong>Sofort-Trigger:</strong> Falls <code>ContainedIPduProps.trigger == always</code> oder <code>ContainerIPduTriggerEnum == firstContainedTrigger</code>, wird die <code>ContainerIPdu</code> unmittelbar an das Interface (<code>CanIf</code>, <code>SoAd</code>) weitergegeben.\n</li><li><strong>Schwellwert-Trigger:</strong> Überschreitet die aggregierte Gesamtlänge <code>thresholdSize</code>, erfolgt sofortiger Push.\n</li><li><strong>Zeitbasierter Trigger:</strong> Läuft der asynchrone Hardware-/Software-Timer <code>containerTimeout</code> oder das PDU-individuelle <code>timeout</code> ab, wird die <code>ContainerIPdu</code> mit dem aktuellen Füllstand asynchron gesendet.\n</li></ul>\n</li></ol>\n<h5 class=\"fig-section-h5\">Empfangs-Pfad (RX-Disaggregation / Unpacking)</h5>\n<ol class=\"fig-list\"><li><strong>Container-Empfang:</strong> Die vollständige <code>ContainerIPdu</code> trifft über das untere Interface (<code>&lt;Bus&gt;If_RxIndication()</code>) im BSW-Stack ein.\n</li><li><strong>Header-Parsing:</strong> Der Byte-Stream wird sequentiell anhand des <code>headerType</code> geparst (Extraktion von ID und Längenfeld).\n</li><li><strong>Validierung &amp; Filterung:</strong>\n<ul class=\"fig-list\"><li>Stimmt die Header-ID mit einer bekannten <code>containedPduTriggering</code> überein, wird die Nutzlast extrahiert.\n</li><li>Ist die ID unbekannt: Bei <code>acceptConfigured</code> Abbruch bzw. PDU-Verwurf (ggf. Det-Meldung); bei <code>acceptAll</code> Weiterspringen um das Längenfeld zum nächsten Header.\n</li></ul>\n</li><li><strong>Dispatchen:</strong> Extrahierte Contained I-PDUs werden über <code>PduR_&lt;Target&gt;RxIndication()</code> an die jeweiligen Zielmodule verteilt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Konfiguration (<code>PduR</code> / CAN FD / Ethernet):</strong>\n<ul class=\"fig-list\"><li>Das Metamodell bildet 1:1 die Konfigurationscontainer <code>PduRContainerIPdu</code> und <code>PduRContainedIPdu</code> im BSW ab.\n</li><li><strong>Konsistenz-Restriktion:</strong> Wenn <code>headerType == shortHeader</code>, muss zwingend <code>headerIdShortHeader</code> gesetzt sein (Bereich: 1 bis 2^24-1). Bei <code>longHeader</code> ist <code>headerIdLongHeader</code> Pflicht (Bereich: 1 bis 2^32-1). Mischbetrieb innerhalb eines Containers ist verboten.\n</li></ul>\n</li><li><strong>Speicher- und Pufferallokation:</strong>\n<ul class=\"fig-list\"><li><code>collectionSemantics == queued</code> erzwingt im BSW-Generat statisch allokierte Ringpuffer (Multi-Element Queues). Entwickler müssen die maximale Queue-Tiefe gegen RAM-Verbrauch und Worst-Case-Latenz abgleichen.\n</li><li><code>lastIsBest</code> minimiert RAM-Overhead (Single-Buffer), führt bei langsamen Buszyklen jedoch zum unbemerkten Verwerfen älterer Datenstände (Data Overwrite).\n</li></ul>\n</li><li><strong>Echtzeit- und Latenz-Design:</strong>\n<ul class=\"fig-list\"><li>Zeitkritische I-PDUs (z. B. Brems-/Lenkanforderungen) müssen zwingend auf <code>trigger = always</code> konfiguriert werden, um ein Verzögern durch <code>containerTimeout</code> zu unterbinden.\n</li><li>Unbedachte Kombinationen von großem <code>thresholdSize</code> und fehlendem <code>containerTimeout</code> können bei unvollständigen Daten zum Blockieren/Verhungern (Starvation) von Contained I-PDUs im Puffer führen.\n</li></ul>\n</li></ul>"}, {"id": "FIG-7157bf2584595c4a", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt des AUTOSAR System Templates (<code>AUTOSAR_TPS_SystemTemplate</code>, PDU-Beschreibung im FIBEX-Modell, R4.2.2).\n</li><li><strong>Technischer Zweck:</strong> Modellierung des PDU-Multiplexings/Packings von mehreren logischen PDUs (<code>ContainedIPdu</code>) in einen gemeinsamen Transportrahmen (<code>ContainerIPdu</code>).\n</li><li><strong>Architektur-Einordnung:</strong> Dient als formale Entwurfsbasis für Kommunikationsstacks mit großen Frame-Kapazitäten (insbesondere CAN FD, FlexRay, Ethernet/SomeIP). Das Modell steuert im BSW-Stack (vor allem <code>PduR</code>, alternativ spezialisierte Module wie <code>IpduM</code>) das Packen, Puffern, Timen und Entpacken heterogener PDUs zur Bandbreitenoptimierung und Overhead-Reduktion.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Metamodell-Klassen &amp; Vererbungen</h5>\n<ul class=\"fig-list\"><li><strong><code>Pdu</code></strong> <em>(«FibexElement, UploadableDesignElement»)</em>:\n<ul class=\"fig-list\"><li>Abstrakte Basisklasse aller Protocol Data Units und ladbares Designelement.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>hasDynamicLength [0..1] : Boolean</code>: Gibt an, ob die PDU eine variable/dynamische Länge besitzt.\n</li><li><code>length [0..1] : UnlimitedInteger</code>: Statische oder maximale PDU-Länge in Byte (unbegrenzter Wertebereich).\n</li></ul>\n</li></ul>\n</li><li><strong><code>IPdu</code></strong>:\n<ul class=\"fig-list\"><li>Spezialisierung von <code>Pdu</code>. Repräsentiert Interaktionsschicht-PDUs.\n</li><li>Komposition: Hält <code>0..1</code> Instanz von <code>ContainedIPduProps</code> über die Rolle <code>+containedIPduProps</code>.\n</li></ul>\n</li><li><strong><code>ContainerIPdu</code></strong>:\n<ul class=\"fig-list\"><li>Spezialisierung von <code>IPdu</code>. Repräsentiert die aggregierende Hüll-PDU.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>containerTimeout [0..1] : TimeValue</code>: Maximales Wartefenster bis zum Zwangsversand unvollständig gefüllter Container.\n</li><li><code>containerTrigger [0..1] : ContainerIPduTriggerEnum</code>: Globales Auslöseverhalten für den Container.\n</li><li><code>headerType [0..1] : ContainerIPduHeaderTypeEnum</code>: Header-Format der eingebetteten PDUs.\n</li><li><code>minimumRxContainerQueueSize [0..1] : PositiveInteger</code>: Mindestgröße der empfangsseitigen Container-Warteschlange.\n</li><li><code>minimumTxContainerQueueSize [0..1] : PositiveInteger</code>: Mindestgröße der sendeseitigen Container-Warteschlange.\n</li><li><code>rxAcceptContainedIPdu [0..1] : RxAcceptContainedIPduEnum</code>: Filterstrategie bei der PDU-Extraktion auf Empfangsseite.\n</li><li><code>thresholdSize [0..1] : PositiveInteger</code>: Füllstandsschwelle in Bytes, bei deren Erreichen/Überschreiten der Container sofort ausgelöst wird.\n</li><li><code>unusedBitPattern [0..1] : PositiveInteger</code>: Bitmuster zum Auffüllen ungenutzter Bereiche im Container.\n</li></ul>\n</li><li>Assoziationen &amp; Kompositionen:\n<ul class=\"fig-list\"><li>Hält <code>0..*</code> <code>+containedPduTriggering</code> (<code>PduTriggering</code>).\n</li><li>Komposition: Hält <code>0..*</code> Instanzen von <code>ContainedIPduProps</code> über die Rolle <code>+containedIPduTriggeringProps</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>ContainedIPduProps</code></strong>:\n<ul class=\"fig-list\"><li>Eigenschafts-Container für eingebettete I-PDUs innerhalb eines Containers.\n</li><li>Attribute:\n<ul class=\"fig-list\"><li><code>collectionSemantics [0..1] : ContainedIPduCollectionSemanticsEnum</code>: Update- und Pufferstrategie (<code>lastIsBest</code> vs. <code>queued</code>).\n</li><li><code>headerIdLongHeader [0..1] : PositiveInteger</code>: 32-Bit-ID bei Verwendung langer Header.\n</li><li><code>headerIdShortHeader [0..1] : PositiveInteger</code>: 24-Bit-ID bei Verwendung kurzer Header.\n</li><li><code>j1939requestable [0..1] : Boolean</code>: Gibt an, ob die enthaltene I-PDU über standardisierte J1939-Request-Mechanismen angefordert werden kann.\n</li><li><code>offset [0..1] : PositiveInteger</code>: Feste Byte-Offset-Position der Contained PDU innerhalb des Containers.\n</li><li><code>priority [0..1] : PositiveInteger</code>: Priorität der Contained PDU bei der Reihenfolge/Auswahl beim Packen.\n</li><li><code>timeout [0..1] : TimeValue</code>: Gültigkeits- bzw. Sammeltimeout der spezifischen Contained I-PDU.\n</li><li><code>trigger [0..1] : PduCollectionTriggerEnum</code>: Legt fest, ob das Eintreffen dieser PDU den sofortigen Containerversand auslöst (<code>always</code> vs. <code>never</code>).\n</li><li><code>updateIndicationBitPosition [0..1] : PositiveInteger</code>: Bitposition des Update-Indication-Bits innerhalb des Containers.\n</li></ul>\n</li><li>Assoziationen &amp; Kompositionen:\n<ul class=\"fig-list\"><li>Assoziiert <code>0..1</code> Instanz von <code>PduTriggering</code> über die Rolle <code>+containedPduTriggering</code>.\n</li></ul>\n</li></ul>\n</li><li><strong><code>PduTriggering</code></strong> <em>(«Identifiable»)</em>:\n<ul class=\"fig-list\"><li>Verbindet eine PDU mit ihrer Übertragung auf einem Kommunikationskanal/Cluster.\n</li><li>Assoziationen:\n<ul class=\"fig-list\"><li>Referenziert <code>0..1</code> <code>+iPdu</code> (<code>Pdu</code>).\n</li></ul>\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Enumerationen</h5>\n<ul class=\"fig-list\"><li><strong><code>ContainerIPduHeaderTypeEnum</code></strong>:\n<ul class=\"fig-list\"><li>Literale: <code>shortHeader</code>, <code>longHeader</code>, <code>noHeader</code>.\n</li></ul>\n</li><li><strong><code>RxAcceptContainedIPduEnum</code></strong>:\n<ul class=\"fig-list\"><li>Literale: <code>acceptAll</code>, <code>acceptConfigured</code>.\n</li></ul>\n</li><li><strong><code>ContainerIPduTriggerEnum</code></strong>:\n<ul class=\"fig-list\"><li>Literale: <code>firstContainedTrigger</code>, <code>defaultTrigger</code>.\n</li></ul>\n</li><li><strong><code>PduCollectionTriggerEnum</code></strong>:\n<ul class=\"fig-list\"><li>Literale: <code>always</code>, <code>never</code>.\n</li></ul>\n</li><li><strong><code>ContainedIPduCollectionSemanticsEnum</code></strong>:\n<ul class=\"fig-list\"><li>Literale: <code>lastIsBest</code>, <code>queued</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<h5 class=\"fig-section-h5\">Sende-Pfad (TX-Aggregation / Packing)</h5>\n<ol class=\"fig-list\"><li><strong>PDU-Anlieferung:</strong> Eine obere Schicht (COM, SecOC, Dcm) übergibt eine I-PDU via <code>PduR_Transmit()</code> an die Routing Engine.\n</li><li><strong>Klassifikation &amp; Pufferung:</strong> \n<ul class=\"fig-list\"><li>Ist der Zielpfad eine <code>ContainerIPdu</code>, prüft das verarbeitende Modul (<code>PduR</code> / IPDU-Multiplexer) <code>ContainedIPduProps</code>.\n</li><li>Bei <code>collectionSemantics == lastIsBest</code> wird ein bestehender Eintrag im TX-Container-Puffer aktualisiert. Bei <code>queued</code> wird die PDU an das Ende des Aggregationspuffers angehängt.\n</li></ul>\n</li><li><strong>Serialisierung:</strong> Voranstellung des Headers (<code>shortHeader</code> oder <code>longHeader</code>) mit der konfigurierten <code>headerIdShortHeader</code> bzw. <code>headerIdLongHeader</code> und der tatsächlichen DLC/Länge.\n</li><li><strong>Trigger-Prüfung:</strong>\n<ul class=\"fig-list\"><li><strong>Sofort-Trigger:</strong> Falls <code>ContainedIPduProps.trigger == always</code> oder <code>ContainerIPduTriggerEnum == firstContainedTrigger</code>, wird die <code>ContainerIPdu</code> unmittelbar an das Interface (<code>CanIf</code>, <code>SoAd</code>) weitergegeben.\n</li><li><strong>Schwellwert-Trigger:</strong> Überschreitet die aggregierte Gesamtlänge <code>thresholdSize</code>, erfolgt sofortiger Push.\n</li><li><strong>Zeitbasierter Trigger:</strong> Läuft der asynchrone Hardware-/Software-Timer <code>containerTimeout</code> oder das PDU-individuelle <code>timeout</code> ab, wird die <code>ContainerIPdu</code> mit dem aktuellen Füllstand asynchron gesendet.\n</li></ul>\n</li></ol>\n<h5 class=\"fig-section-h5\">Empfangs-Pfad (RX-Disaggregation / Unpacking)</h5>\n<ol class=\"fig-list\"><li><strong>Container-Empfang:</strong> Die vollständige <code>ContainerIPdu</code> trifft über das untere Interface (<code>&lt;Bus&gt;If_RxIndication()</code>) im BSW-Stack ein.\n</li><li><strong>Header-Parsing:</strong> Der Byte-Stream wird sequentiell anhand des <code>headerType</code> geparst (Extraktion von ID und Längenfeld).\n</li><li><strong>Validierung &amp; Filterung:</strong>\n<ul class=\"fig-list\"><li>Stimmt die Header-ID mit einer bekannten <code>containedPduTriggering</code> überein, wird die Nutzlast extrahiert.\n</li><li>Ist die ID unbekannt: Bei <code>acceptConfigured</code> Abbruch bzw. PDU-Verwurf (ggf. Det-Meldung); bei <code>acceptAll</code> Weiterspringen um das Längenfeld zum nächsten Header.\n</li></ul>\n</li><li><strong>Dispatchen:</strong> Extrahierte Contained I-PDUs werden über <code>PduR_&lt;Target&gt;RxIndication()</code> an die jeweiligen Zielmodule verteilt.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSW-Konfiguration (<code>PduR</code> / CAN FD / Ethernet):</strong>\n<ul class=\"fig-list\"><li>Das Metamodell bildet 1:1 die Konfigurationscontainer <code>PduRContainerIPdu</code> und <code>PduRContainedIPdu</code> im BSW ab.\n</li><li><strong>Konsistenz-Restriktion:</strong> Wenn <code>headerType == shortHeader</code>, muss zwingend <code>headerIdShortHeader</code> gesetzt sein (Bereich: 1 bis 2^24-1). Bei <code>longHeader</code> ist <code>headerIdLongHeader</code> Pflicht (Bereich: 1 bis 2^32-1). Mischbetrieb innerhalb eines Containers ist verboten.\n</li></ul>\n</li><li><strong>Speicher- und Pufferallokation:</strong>\n<ul class=\"fig-list\"><li><code>collectionSemantics == queued</code> erzwingt im BSW-Generat statisch allokierte Ringpuffer (Multi-Element Queues). Entwickler müssen die maximale Queue-Tiefe gegen RAM-Verbrauch und Worst-Case-Latenz abgleichen.\n</li><li><code>lastIsBest</code> minimiert RAM-Overhead (Single-Buffer), führt bei langsamen Buszyklen jedoch zum unbemerkten Verwerfen älterer Datenstände (Data Overwrite).\n</li></ul>\n</li><li><strong>Echtzeit- und Latenz-Design:</strong>\n<ul class=\"fig-list\"><li>Zeitkritische I-PDUs (z. B. Brems-/Lenkanforderungen) müssen zwingend auf <code>trigger = always</code> konfiguriert werden, um ein Verzögern durch <code>containerTimeout</code> zu unterbinden.\n</li><li>Unbedachte Kombinationen von großem <code>thresholdSize</code> und fehlendem <code>containerTimeout</code> können bei unvollständigen Daten zum Blockieren/Verhungern (Starvation) von Contained I-PDUs im Puffer führen.\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-a6973e9bc6ba6008", "to": "FIG-9c9028f9b9c7f28a", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong><code>Pdu</code></strong>: Attribut <code>metaDataLength : PositiveInteger [0..1]</code> entfernt.\n</li><li><strong><code>Pdu</code> / <code>PduTriggering</code></strong>: Multiplizität am Assoziationsende bei <code>PduTriggering</code> von <code>1..*</code> entfernt (nicht mehr beschriftet).\n</li><li><strong><code>ContainerIPdu</code></strong>: Attribut <code>unusedBitPattern : PositiveInteger [0..1]</code> hinzugefügt.\n</li><li><strong><code>ContainerIPduHeaderTypeEnum</code></strong>: Literal <code>noHeader</code> hinzugefügt.\n</li><li><strong><code>ContainedIPduProps</code></strong>: Attribute <code>offset : PositiveInteger [0..1]</code> und <code>updateIndicationBitPosition : PositiveInteger [0..1]</code> hinzugefügt.\n</li></ul>"}, {"from": "FIG-9c9028f9b9c7f28a", "to": "FIG-83ebb46286560252", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong><code>Pdu</code></strong>: Attribut <code>hasDynamicLength : Boolean [0..1]</code> hinzugefügt.\n</li><li><strong><code>ContainerIPdu</code></strong>: Attribute <code>minimumRxContainerQueueSize : PositiveInteger [0..1]</code> und <code>minimumTxContainerQueueSize : PositiveInteger [0..1]</code> hinzugefügt.\n</li><li><strong><code>ContainedIPduProps</code></strong>: Attribut <code>priority : PositiveInteger [0..1]</code> hinzugefügt.\n</li></ul>"}, {"from": "FIG-83ebb46286560252", "to": "FIG-e636a31c8dabba57", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-e636a31c8dabba57", "to": "FIG-8778e0babe527f2e", "fr": "R20-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong><code>Pdu</code></strong>: Datentyp von <code>length</code> von <code>Integer [0..1]</code> auf <code>UnlimitedInteger [0..1]</code> geändert.\n</li><li><strong><code>ContainerIPdu</code></strong>: Komposition zu <code>ContainedIPduProps</code> mit Rollenname <code>+containedIPduTriggeringProps</code> und Multiplizität <code>0..*</code> hinzugefügt.\n</li><li><strong><code>ContainedIPduProps</code></strong>: Gerichtete Assoziation zu <code>PduTriggering</code> mit Rollenname <code>+containedPduTriggering</code> und Multiplizität <code>0..1</code> hinzugefügt.\n</li></ul>"}, {"from": "FIG-8778e0babe527f2e", "to": "FIG-1d9f5110ae350f17", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong><code>Pdu</code></strong>: Stereotyp bzw. Klassifikation <code>UploadableDesignElement</code> ergänzt (<code>«FibexElement, UploadableDesignElement»</code>).\n</li><li><strong><code>PduTriggering</code></strong>: Multiplizität der Assoziationsrolle <code>+iPdu</code> von <code>1</code> auf <code>0..1</code> gelockert.\n</li><li><strong><code>ContainerIPdu</code></strong>: Multiplizität von <code>headerType</code> von <code>1</code> auf <code>[0..1]</code> gelockert; Multiplizität von <code>rxAcceptContainedIPdu</code> von <code>1</code> auf <code>[0..1]</code> gelockert.\n</li><li><strong><code>ContainedIPduProps</code></strong>: Multiplizität von <code>collectionSemantics</code> von <code>1</code> auf <code>[0..1]</code> gelockert.\n</li></ul>"}, {"from": "FIG-1d9f5110ae350f17", "to": "FIG-982ca8cec76fad31", "fr": "R23-11", "tr": "R24-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Enumerationen (<code>ContainerIPduHeaderTypeEnum</code>, <code>RxAcceptContainedIPduEnum</code>, <code>PduCollectionTriggerEnum</code>, <code>ContainerIPduTriggerEnum</code>, <code>ContainedIPduCollectionSemanticsEnum</code>)</strong>: Abschnittsüberschrift bzw. Schlüsselwort <code>literals</code> in den Aufzählungsblöcken ergänzt.\n</li></ul>"}, {"from": "FIG-982ca8cec76fad31", "to": "FIG-7157bf2584595c4a", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Attribut <code>j1939requestable [0..1] : Boolean</code> zu Klasse <code>ContainedIPduProps</code> hinzugefügt.\n</li></ul>"}]};
